function normativeBody(c){
 const n=c.normative;if(!n)return '';
 const ps=n.points||[];
 return `<section class="normative-sheet">${ps.length===1?`<p class="memory-core">${esc(ps[0])}</p>`:`<div class="normative-points">${ps.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`}${n.context?`<p class="p-muted">${esc(n.context)}</p>`:''}${(n.quotes||[]).map(q=>`<blockquote><p>${esc(q.text)}</p><small>${esc(q.label)}</small></blockquote>`).join('')}</section>`;
}
function relationshipNotice(c){
 const e=c.essay;if(!e?.relationshipIDs?.length)return '';
 const r=D.relationGuide.relations.find(r=>r.id===e.relationshipIDs[0]),id='REL'+c.cat+r.id.slice(1);
 return `<section class="relationship-notice"><p class="memory-label">把关系写清 · ${esc(r.title)}</p><p>${esc(r.judgment)}</p><p class="memory-chain">${esc(r.chain)}</p><details><summary>分论点怎样围绕关系展开</summary><ol>${r.axes[c.cat].map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>${esc(r.boundary)}</p></details><div class="track-actions"><button class="chip" data-cardlink="${id}">直接背对应段落与结构</button></div>${e.relationshipReview?`<p class="small-copy">${esc(e.relationshipReview)}</p>`:''}</section>`
}
function relationReader(){
 const selected=S.group==='国开行'?'W':S.group==='上海选调'?'S':null;
 return `<section class="chapter-head"><p class="eyebrow">申论 · 关系型论证</p><h1>八组关系：判断、机制与边界</h1><p>${esc(D.relationGuide.principle)}</p></section><div class="filters">${['全部','国开行','上海选调'].map(x=>`<button class="chip ${S.group===x?'selected':''}" data-group="${x}">${x}</button>`).join('')}</div><div class="relationship-index">${D.relationGuide.relations.map(r=>`<button class="chip" data-sectionjump="relation-${r.id}">${esc(r.title)}</button>`).join('')}</div>${D.relationGuide.relations.map((r,n)=>`<article class="card relation-chapter" id="relation-${r.id}"><p class="memory-label">${n+1} / 8</p><h2>${esc(r.title)}</h2><h3>先背关系判断</h3><p class="relation-judgment">${esc(r.judgment)}</p><p class="memory-chain">${esc(r.chain)}</p><h3>易错边界</h3><p>${esc(r.boundary)}</p>${(selected?[selected]:['W','S']).map(k=>`<section class="recitation-paragraph"><h3>${k==='W'?'国开行：金融服务与发展':'上海选调：治理与发展'}</h3><p>${esc(r.paragraphs[k])}</p><h4>文章结构：三个分论点</h4><ol>${r.axes[k].map(t=>`<li>${esc(t)}</li>`).join('')}</ol><button class="chip" data-cardlink="REL${k}${r.id.slice(1)}">单独背这一段</button></section>`).join('')}</article>`).join('')}`
}

function recitationBody(c,print=false){if(c.normative)return normativeBody(c);
 const r=c.recitation;if(!r)return '';
 const brief=S.readMode==='brief';
 let h=`<section class="recitation-sheet">${r.kind?`<p class="memory-label">${esc(r.kind)}</p>`:''}<section class="recitation-background"><h3>背景与时间</h3><p>${esc(r.background)}</p></section><section><h3>核心内容</h3><div class="recitation-facts">${r.core.map(t=>`<p>${esc(t)}</p>`).join('')}</div></section>`;
 if(r.quotes?.length)h+=`<section><h3>必背原话</h3>${r.quotes.map(q=>`<blockquote class="speech-quote ${q.label.startsWith('陈吉宁')?'chen-quote':''}"><span>${esc(q.label)}</span><p>“${esc(q.text)}”</p></blockquote>`).join('')}</section>`;
 if(!brief&&r.recite)h+=`<section class="recitation-paragraph"><h3>必背表述 · 理解记忆</h3><p>${esc(r.recite)}</p></section>`;
 if(r.exam?.length)h+=`<section class="recitation-exam"><h3>易考与易混</h3>${r.exam.map(t=>`<p>${esc(t)}</p>`).join('')}</section>`;
 if(c.relatedLeadership?.length&&!print)h+=`<div class="track-actions">${c.relatedLeadership.map(id=>`<button class="chip" data-cardlink="${id}">${esc(D.cards.find(c=>c.id===id).title)}</button>`).join('')}</div>`;
 return h+'</section>'
}
function speechSpecial(){
 const g=D.speechSpecial,group=S.group;
 const part=(title,ids)=>`<section class="speech-part"><h2>${title}</h2>${ids.map(id=>{const c=D.cards.find(c=>c.id===id);return `<article class="card speech-article"><h2>${esc(c.title)}</h2>${recitationBody(c)}<div class="track-actions"><button class="chip" data-cardlink="${id}">单独背这一专题</button><button class="chip" data-star="${id}">${S.stars.has(id)?'★ 已收藏':'☆ 收藏'}</button></div>${sourceFold(c)}</article>`}).join('')}</section>`;
 const quotes=[...g.xi,...g.chen].flatMap(id=>{const c=D.cards.find(c=>c.id===id);return (c.recitation.quotes||[]).map(q=>`<article class="card"><p class="memory-label">${esc(c.title)}</p><blockquote class="speech-quote ${q.label.startsWith('陈吉宁')?'chen-quote':''}"><span>${esc(q.label)}</span><p>“${esc(q.text)}”</p></blockquote><button class="chip" data-cardlink="${id}">查看完整表述</button></article>`)}).join('');
 return `<section class="chapter-head"><p class="eyebrow">时政专题 · 上海工作重要论述</p><h1>习近平重要论述<br>陈吉宁讲话与市委部署</h1><p>直接背诵讲话原句、重要部署与完整名称。</p></section><div class="filters">${['全部','原话速记','时间线','习近平','陈吉宁与市委','治理概念'].map(t=>`<button class="chip ${group===t?'selected':''}" data-group="${t}">${t}</button>`).join('')}</div>${group==='原话速记'?quotes:''}${['全部','时间线'].includes(group)?`<section class="speech-timeline"><h2>2026年六个节点</h2>${g.timeline.map(([date,event,id])=>`<button data-cardlink="${id}"><b>${esc(date)}</b><span>${esc(event)}</span></button>`).join('')}</section>`:''}${['全部','习近平'].includes(group)?part('一、习近平关于上海工作的重要论述',g.xi):''}${['全部','陈吉宁与市委'].includes(group)?part('二、陈吉宁讲话与市委部署',g.chen):''}${['全部','治理概念'].includes(group)?part('三、基层工作概念与对应关系',g.terms):''}`
}
function leadershipSpecial(){
 return `<section class="chapter-head"><p class="eyebrow">政治理论与申论共用专题</p><h1>长期执政的领导力</h1><p>总逻辑：把方向 → 凝共识 → 组织群众 → 专业执行 → 监督纠偏 → 成效与信任。</p></section>${D.leadershipSpecial.map(id=>{const c=D.cards.find(c=>c.id===id);return `<article class="card"><h2>${esc(c.title)}</h2>${c.essay?essayBody(c):recitationBody(c)}${sourceFold(c)}</article>`}).join('')}`
}
function knowledgeGuide(){
 if(S.view==='H')return `<section class="knowledge-guide"><h2>行史与市情 · 按对象背</h2><div class="track-actions"><button class="chip" data-course="H" data-domain="国开行">国开：定位 → 行史 → 文化 → 业务与数据</button><button class="chip" data-course="H" data-domain="上海">上海：城市定位 → 重要论述 → 治理与市情</button><button class="chip" data-nav="shspeeches">习近平与陈吉宁上海论述专题</button><button class="chip" data-course="H" data-domain="邮储银行">邮储</button><button class="chip" data-course="H" data-domain="农业银行">农行</button></div></section>`;
 if(['T','N'].includes(S.view))return `<section class="knowledge-guide"><h2>${S.view==='T'?'金融时政：政策方向、工具机制与数据口径':'通用时政：规划、发展、科技、民生与治理'}</h2><div class="track-actions"><button class="chip" data-nav="shspeeches">上海重要论述</button><button class="chip" data-nav="leadership">长期执政领导力</button>${[...new Set(D.cards.filter(c=>(c.cat===S.view||c.categoryTags?.includes(S.view))&&!c.mergedInto).map(c=>c.group))].map(g=>`<button class="chip" data-group="${esc(g)}">${esc(g)}</button>`).join('')}</div></section>`;
 return ''
}

function examDashboard(track){
 const sh=track==='shtrack',title=sh?'上海选调 · 按考试内容复习':'国开行 · 按考试内容复习';
 const groups=sh?[
 ['行测 · 政治理论',[['P','政治理论与辨析'],['N','通用时政与政策']]],
 ['行测 · 常识与地方知识',[['H','上海市情与地方时政','上海'],['C','科学推理 · 独立学习章']]],
 ['行测 · 言语理解与判断推理',[['V','言语、篇章阅读与病句'],['J','逻辑、定义、类比与图形']]],
 ['行测 · 数理应用与综合分析',[['M','数量关系与数学'],['资料分析','资料分析18组公式'],['T','经济金融材料阅读背景']]],
 ['申论 · 主题与题型',[['S','按主题找好句和结构'],['S','小题与应用文结构','','题型结构与规范表达']]]
 ]:[
 ['英语能力',[['U','词汇、语法与阅读']]],
 ['EPI与综合能力',[['V','言语理解'],['J','判断推理'],['M','数量关系'],['资料分析','资料分析常用公式']]],
 ['专业知识与计算',[['F','金融学'],['E','经济学'],['A','会计财务'],['G','管理与经济法'],['K','历年考法与计算机基础'],['calc','年金 / NPV / YTM / PE']]],
 ['行史与时政',[['H','国开行行史行况','国开行'],['T','金融时政'],['N','通用时政']]],
 ['综合写作与申论',[['W','主题好句与论证结构'],['W','小题与应用文结构','','题型结构与规范表达']]]
 ];
 const link=([v,label,domain,group])=>`<button class="module" ${v==='资料分析'?'data-recite="资料分析"':domain||group?`data-course="${v}" data-domain="${domain||'全部'}" data-setgroup="${group||'全部'}"`:`data-nav="${v}"`}><h3>${esc(label)}</h3><span>打开背诵材料 →</span></button>`;
 return `<section class="chapter-head"><p class="eyebrow">考试主线</p><h1>${title}</h1><p>先看必背内容，需要时展开例题、结构和原资料。</p><button class="secondary" data-recite="${sh?'上海必背':'国开必背'}">直接背本场相关知识</button><button class="chip" data-nav="library">查看全库资料与使用情况</button></section>${groups.map(([name,items])=>`<section class="exam-block"><h2>${name}</h2><div class="module-grid">${items.map(link).join('')}</div></section>`).join('')}<details class="memory-extra"><summary>结构依据与适用范围</summary><p>${esc(D.library.examBasis[sh?'sh':'cdb'])}</p>${sh?'<button class="cite" data-source="LIBSHOFF">上海公告科目说明</button>':''}<p>历年回忆与机构模拟均为复习材料，不据文件名保证官方身份；本年度安排以正式通知为准。</p></details>`
}
function libraryReader(){
 const lib=D.library,q=(S.libQuery||'').toLowerCase();let arr=lib.files.filter(f=>(S.group==='全部'||f.category===S.group)&&(!q||(f.name+' '+f.category+' '+f.status).toLowerCase().includes(q)));
 const pages=Math.max(1,Math.ceil(arr.length/25));S.page=Math.max(1,Math.min(S.page,pages));
 return `<section class="chapter-head"><p class="eyebrow">全库可追溯目录</p><h1>资料总目录与使用情况</h1><p>${lib.stats.physical}份文档，按内容去重后${lib.stats.unique}份；${lib.stats.duplicateCopies}份相同内容副本保留。本轮从${lib.stats.usedSources}份资料提炼或补充关联，新增${lib.stats.newCards}张知识卡。清点、文本抽取与逐题精读分开标注。</p><button class="secondary" data-recite="全库新增">先背新增内容</button></section><label>查找文件 <input id="librarySearch" type="search" value="${esc(S.libQuery||'')}" placeholder="输入文件名、科目或使用状态"></label><button class="chip" data-libsearch="1">查找</button><div class="filters">${['全部',...new Set(lib.files.map(f=>f.category))].map(t=>`<button class="chip ${S.group===t?'selected':''}" data-group="${esc(t)}">${esc(t)}</button>`).join('')}</div><p>${arr.length}份 · 第${S.page}/${pages}页</p>${arr.slice((S.page-1)*25,S.page*25).map(f=>`<article class="card"><div class="card-id">${esc(f.category)} · ${f.pages}页/文本单元 · ${f.copies}份副本</div><h2>${esc(f.name)}</h2><p>${esc(f.status)} · ${esc(f.read)}</p><div class="track-actions">${f.cards.map(id=>`<button class="chip" data-cardlink="${id}">${esc(D.cards.find(c=>c.id===id)?.title||id)}</button>`).join('')}<a class="source-link" href="${f.href}" target="_blank" rel="noopener">打开归档资料</a></div></article>`).join('')}<div class="pager"><button data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><span>${S.page}/${pages}</span><button data-page="${S.page+1}" ${S.page===pages?'disabled':''}>下一页</button></div>`
}

function reciteShelf(){
 S.readMode='memory';
 const options=[['全部','全部'],['新增','重点精要'],['W','国开申论'],['S','上海申论'],['H','行史与市情'],['T','金融时政'],['N','通用时政'],['C','科学推理'],['F','金融'],['E','经济'],['A','会计财管'],['G','管理与经济法'],['K','国开专业考法'],['M','数学']];
 let all=D.cards.filter(c=>!c.mergedInto&&!D.readingAliases?.[c.id]);
 options.splice(2,0,['国开必背','国开必背'],['上海必背','上海必背'],['全库新增','各科补充'],['P','政治理论'],['V','言语'],['J','判断'],['U','国开英语'],['资料分析','资料分析公式']);
 if(['国开必背','上海必背'].includes(S.group)){const sh=S.group==='上海必背';all=all.filter(c=>c.cat==='H'?(c.domain===(sh?'上海':'国开行')):(sh?['P','V','J','M','C','S','T','N']:['U','V','J','M','E','F','A','G','K','W','T','N']).includes(c.cat))}else if(S.group==='全库新增')all=all.filter(c=>D.library.newIds.includes(c.id));else if(S.group==='资料分析')all=all.filter(c=>c.group==='资料分析常用公式');else if(S.group==='新增')all=all.filter(c=>D.audit.newIds.includes(c.id));else if(options.some(([k])=>k===S.group)&&S.group!=='全部')all=all.filter(c=>c.cat===S.group);
 const order=c=>D.audit.newIds.includes(c.id)?0:c.essay?.type==='common'?1:2;all.sort((a,b)=>order(a)-order(b));
 const count=Math.ceil(all.length/12)||1;S.page=Math.min(count,Math.max(1,S.page));
 return `<section class="chapter-head"><p class="eyebrow">打开就背</p><h1>必背材料</h1><p>定义、公式、易错点和申论段落直接展示。点收藏可留下重点，点已掌握记录进度。</p></section><div class="recite-filter" aria-label="必背章节">${options.map(([k,t])=>`<button class="chip ${S.group===k?'selected':''}" data-group="${k}">${t}</button>`).join('')}</div><div class="reader-toolbar"><b>${all.length}张 · 第${S.page}/${count}页</b><button class="chip" data-nav="calc">年金 / NPV / YTM计算</button></div>${all.slice((S.page-1)*12,S.page*12).map(c=>{const m=c.memory;let text=c.essay?essayBody(c):memoryFront(c);return `<article class="card recite-visible"><div class="card-id">${c.id} · ${esc(META[c.cat].name)}</div><h2>${esc(c.title)}</h2><div class="prose">${text}</div><div class="track-actions"><button class="chip" data-cardlink="${c.id}">完整知识卡</button><button class="chip" data-star="${c.id}">${S.stars.has(c.id)?'★ 已收藏':'☆ 收藏'}</button><button class="chip" data-known="${c.id}">${S.known.has(c.id)?'✓ 已掌握':'○ 标记掌握'}</button></div></article>`}).join('')}<div class="pager"><button data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><span>${S.page} / ${count}</span><button data-page="${S.page+1}" ${S.page===count?'disabled':''}>下一页</button></div>`
}
function auditReader(){
 const a=D.audit;let rows=a.rows;
 if(S.group==='模拟专业')rows=rows.filter(r=>r.id.startsWith('M'));if(S.group==='历年专业')rows=rows.filter(r=>r.id.startsWith('Y'));if(S.group==='主观题')rows=rows.filter(r=>r.id.startsWith('S'));if(S.group==='疑题与历史')rows=rows.filter(r=>/历史|疑题|待核|勘误|缺|不全/.test(r.status));
 const count=Math.ceil(rows.length/20)||1;S.page=Math.max(1,Math.min(count,S.page));
 return `<section class="chapter-head"><p class="eyebrow">查阅附录</p><h1>国开行逐卷核对</h1><p>27个文件中23个与专业/主观题相关；3套专业模拟卷185题已逐题核对并关联。历年表为题目/考点定位，关联不等于所有原答案均正确。</p><button class="secondary" data-recite="新增">直接背本轮补漏 →</button></section><details class="memory-extra"><summary>原资料缺口与待核项 · ${a.unresolved.length}项</summary>${a.unresolved.map(x=>`<p><b>${esc(x.file)}</b>：${esc(x.issue)}</p>`).join('')}</details><details class="memory-extra"><summary>全部23份相关文件与检查范围</summary>${a.files.map(f=>`<p><b>${esc(f.file)}</b> · ${esc(f.pages)}<br>${esc(f.note)}</p>`).join('')}</details><div class="filters">${['全部','模拟专业','历年专业','主观题','疑题与历史'].map(t=>`<button class="chip ${S.group===t?'selected':''}" data-group="${t}">${t}</button>`).join('')}</div><p>${rows.length}条定位 · 第${S.page}/${count}页</p>${rows.slice((S.page-1)*20,S.page*20).map(r=>`<article class="card"><div class="card-id">${esc(r.id)} · ${esc(r.status)}</div><h2>${esc(r.topic)}</h2><p class="small-copy">${esc(r.file)} · ${esc(r.page)} · ${esc(r.question)}</p><p>${esc(r.note)}</p><div class="track-actions">${r.cards.map(id=>`<button class="chip" data-cardlink="${id}">${esc(D.cards.find(c=>c.id===id).title)}</button>`).join('')}</div>${r.raw?`<details><summary>原题原文（保留原答案，不代表认证）</summary><p style="white-space:pre-wrap">${esc(r.raw)}</p></details>`:''}<a class="source-link" href="${esc(r.href)}${/^\d/.test(r.page)?'#page='+parseInt(r.page):''}" target="_blank" rel="noopener">打开原资料</a></article>`).join('')}<div class="pager"><button data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><span>${S.page} / ${count}</span><button data-page="${S.page+1}" ${S.page===count?'disabled':''}>下一页</button></div>`
}


'use strict';
const D=JSON.parse(document.getElementById('studyData').textContent);
function hydrateParagraphs(v){if(Array.isArray(v))return v.map(hydrateParagraphs);if(v&&typeof v==='object'){if(v.$paragraph)return D.paragraphPool[v.$paragraph];for(const k of Object.keys(v))v[k]=hydrateParagraphs(v[k]);}return v;}
for(const c of D.cards)if(c.essay)c.essay=hydrateParagraphs(c.essay);
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
