function memoryFront(c){if(c.normative)return normativeBody(c);
 if(c.recitation)return recitationBody(c);
 const m=c.memory||{points:[c.title],keywords:[]};
 return `<section class="memory-front"><div class="memory-label">记忆核心</div>${m.points.length===1?`<p class="memory-core">${esc(m.points[0])}</p>`:`<ol class="memory-points">${m.points.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`}${m.boundary?`<p class="memory-boundary"><b>条件一起记：</b>${esc(m.boundary)}</p>`:''}</section>`
}

function themeTeaching(c){
 const t=c.essay?.teaching;if(!t)return '';
 const blocks=(arr)=>arr.map(([role,text])=>`<div class="theme-step"><b>${esc(role)}</b><p>${esc(text)}</p></div>`).join('');
 return `<section class="theme-teaching"><p class="memory-label">${esc(t.topic)} · 好句、逻辑与结构</p><h3>标志性词组</h3><div class="memory-keywords">${t.axes.map(x=>`<span>${esc(x)}</span>`).join('')}</div><h3>主题好句 · 整理表达</h3><ul>${t.goodSentences.map(x=>`<li><strong>${esc(x)}</strong></li>`).join('')}</ul><h3>论证逻辑链</h3><p class="memory-chain">${esc(t.logic)}</p><h3>三个展开角度</h3><ol>${t.axes.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${S.readMode==='brief'?'':`<h3>一段怎么写：观点—机制—材料—分析—回扣</h3>${blocks(t.paragraph)}<h3>一篇怎么搭：总论点＋三个分论点＋收束</h3>${blocks(t.outline)}<p class="memory-boundary">${esc(t.relation)}</p>`}</section>`
}
function themeDirectory(){
 if(!['W','S'].includes(S.view))return '';
 const cards=D.cards.filter(c=>(c.cat===S.view||c.categoryTags?.includes(S.view))&&c.essay?.teaching),topics=[...new Set(cards.map(c=>c.essay.teaching.topic))];
 return `<section class="theme-directory"><h2>按主题找素材与结构</h2><div class="track-actions"><button class="secondary" data-nav="relations">国家与地方等八组关系 · 判断与段落</button><button class="chip" data-course="${S.view}" data-setgroup="关系型论证">本场八组关系模板</button></div><button class="chip" data-course="${S.view}" data-setgroup="题型结构与规范表达">概括 / 分析 / 对策 / 启示 / 应用文 / 大作文结构</button><p>每个主题：标志词组 → 好句 → 逻辑链 → 段落结构 → 全文框架。名言与范文在对应主题内关联。</p>${topics.map(t=>`<details open><summary>${esc(t)}</summary><div class="track-actions">${cards.filter(c=>c.essay.teaching.topic===t).map(c=>`<button class="chip" data-cardlink="${c.id}">${esc(c.title.split('：')[0])}</button>`).join('')}</div></details>`).join('')}</section>`
}

function essayBody(c,print=false){
 const e=c.essay,brief=S.readMode==='brief',full=S.readMode==='full';
 let h=`<section class="essay-core"><span class="memory-label">一句话背诵</span><p>${esc(e.core)}</p></section><div class="memory-keywords">${(e.keywords||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`;
 h+=relationshipNotice(c);
 h+=themeTeaching(c);
 if(e.type==='common'){
  h+=`<section class="verified-quote"><span class="memory-label">习近平总书记重要论述 · 原句${e.quote.endsWith('。')?'':'节选'}</span><blockquote>“${esc(e.quote)}”</blockquote></section><p class="memory-chain">${esc(e.chain)}</p>`;
  if(!brief)h+=`<section class="sentence-collection"><h3>范文与材料中的例证</h3><p>${esc(e.case)}</p></section><section class="recite-paragraph"><h3>可直接背诵的展开段 · 教学整理</h3><p>${esc(e.paragraph)}</p></section><div class="sentence-frame"><h3>论证怎样展开</h3><p>${esc(e.modelLogic)}</p><p>本专题落点：${esc(e.transfer)}</p></div><p class="memory-boundary">${esc(e.pitfall)}</p>`;
 }else if(e.type==='theme'){
  h+=`<p class="memory-chain">${esc(e.chain)}</p>`;
  if(e.standardNames?.length)h+=`<div class="standard-names"><span>规范名称</span>${e.standardNames.map(t=>'<p>'+esc(t)+'</p>').join('')}</div>`;
  const paragraph=`<section class="recite-paragraph"><h3>成段背诵</h3><p>${esc(e.paragraph)}</p></section>`;
  h+=brief&&!print?`<details class="memory-extra"><summary>展开成段素材</summary>${paragraph}</details>`:brief?'':paragraph;
  if(!brief)h+=`<section class="sentence-collection"><h3>短句积累</h3><ul>${e.sentences.map(t=>'<li>'+esc(t)+'。</li>').join('')}</ul></section><div class="sentence-frame"><h3>可替换句式</h3><p>${esc(e.frame)}</p></div>`;
  if(!print&&e.modelLinks?.length)h+=`<div class="related-knowledge">同主题范文：${e.modelLinks.map(id=>`<button class="chip" data-cardlink="${id}">${esc(D.cards.find(c=>c.id===id)?.title||id)}</button>`).join('')}</div>`;
 }else if(e.type==='bank'){
  h+=e.sections.map(([name,items])=>`<section class="sentence-collection"><h3>${esc(name)}</h3><ul>${items.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul></section>`).join('');
 }else if(e.type==='skeleton'){
  h+=`<div class="paragraph-skeleton">${e.steps.map(([role,t],n)=>`<section><span class="skeleton-number">${n+1}</span><div><h3>${esc(role)}</h3><p>${esc(t)}</p></div></section>`).join('')}</div><section class="recite-paragraph"><h3>连起来就是一段</h3><p>${esc(e.steps.map(x=>x[1]).join(''))}</p></section>`;
 }else if(e.type==='model'){
  h+=`<section class="model-axis"><h3>全篇记忆骨架</h3><p>${esc(e.axis)}</p></section><section class="model-extracts"><h3>范文好句与展开方式</h3>${e.paragraphs.map((p,n)=>`<div class="model-extract"><span>${n+1} · ${esc(p.role)}</span><p>${esc(p.extract)}</p><small>展开方式：${esc(p.pattern)}</small></div>`).join('')}</section>`;
  const article=`<div class="complete-model"><h3>${esc(c.title)}</h3>${e.paragraphs.map((p,n)=>`<section class="model-paragraph"><div class="paragraph-role">${n+1} · ${esc(p.role)}</div><p>${esc(p.text)}</p><div class="paragraph-teaching"><b>段落展开：</b>${esc(p.pattern)}</div></section>`).join('')}</div>`;
  if(print&&!brief)h+=article;
  else if(!print)h+=`<details class="whole-model" ${full?'open':''}><summary>整篇范文与分段精读 · ${e.paragraphs.length}段 / ${e.paragraphs.reduce((n,p)=>n+p.text.length,0)}字</summary>${article}</details>`;
 }
 if(e.commonLinks?.length)h+=`<section class="common-link"><h3>同主题常用论据</h3><p>${esc(e.commonCue)}</p>${!print?e.commonLinks.map(id=>`<button class="chip" data-cardlink="${id}">原句释义、材料例证与背诵段 →</button>`).join(''):''}</section>`;
 if(!print&&c.legacyTitle)h+=`<details class="memory-archive"><summary>例题与延伸讲解</summary><div class="archived-content">${c.html}</div></details>`;
 return h
}

function memoryContentBeforeCity(c,print=false){if(c.normative)return normativeBody(c);
 if(c.recitation)return recitationBody(c,print);
 if(c.essay)return essayBody(c,print);
 const front=memoryFront(c);let original=bodyFor(c,print);
 if(c.lesson&&!print){if(S.mathAnswers.has(c.id))original=original.replace('data-math-answer="'+c.id+'"','data-math-answer="'+c.id+'" open');if(S.mathSolutions.has(c.id))original=original.replace('data-math-solution="'+c.id+'"','data-math-solution="'+c.id+'" open')}
 if(S.readMode==='full')return front+'<section class="full-explanation"><h3>详解与例题</h3>'+original+'</section>';
 return front+(print?'':`<details class="memory-full"><summary>展开完整讲解、公式推导与例题</summary><div class="full-explanation">${original}</div></details>`)
}

