function navLegacy(){
 const n=k=>D.cards.filter(c=>!c.mergedInto&&(c.cat===k||c.categoryTags?.includes(k))).length,item=(key,symbol,label,count='')=>`<button data-nav="${key}" class="${S.view===key?'active':''}" ${S.view===key?'aria-current="page"':''}><span class="nav-symbol">${symbol}</span>${label}<small>${count}</small></button>`;
 $('nav').innerHTML=item('home','⌂','背诵总览')+item('cdbtrack','国','国开行 · 考试主线')+item('shtrack','沪','上海选调 · 考试主线')+item('recite','背','直接背 · 必背材料')+'<button data-recite="资料分析"><span class="nav-symbol">式</span>资料分析常用公式<small>18</small></button>'+'<div class="nav-label">申论背诵素材 · 两部分</div>'+item('W','国','国开行申论素材',n('W'))+item('S','沪','上海申论素材',n('S'))+item('relations','系','申论八组关系与模板')+'<div class="nav-label">知识速记</div>'+['P','V','J','U'].map(k=>item(k,k,META[k].name,n(k))).join('')+item('K','题','国开行专业考法',n('K'))+item('C','理','科学推理',n('C'))+item('H','史','行史行况与上海市情',n('H'))+'<div class="nav-label">共用时政</div>'+item('shspeeches','沪','习近平与陈吉宁上海论述')+item('leadership','领','长期执政的领导力')+item('T','金','金融时政',n('T'))+item('N','时','通用时政',n('N'))+'<div class="nav-label">共用专业</div>'+item('calc','算','财务计算专题')+['E','F','A','G','M'].map(k=>item(k,k,META[k].name,n(k))).join('')+'<div class="nav-label">查阅与附录</div>'+item('stars','☆','我的收藏',S.stars.size||'')+item('last','↗','综合速记表')+item('quiz','?','专项自测',D.quiz.length)+item('newsfull','文','时政原文全文')+item('exams','卷','题卷考点索引')+item('library','库','975份资料总目录')+item('audit','核','国开行逐卷核对')+item('proindex','专','专业题卷关联')+item('sources','≡','出处与依据')+item('roadmap','✓','版本说明')+'<div class="nav-label">后续备考</div><button data-course="H" data-domain="邮储银行"><span class="nav-symbol">邮</span>邮储银行</button><button data-course="H" data-domain="农业银行"><span class="nav-symbol">农</span>农业银行</button>';progress()
}
function go(view,jump){if(jump){jump=canonicalCardId(jump);view=cardMap.get(jump)?.cat||view;}S.view=view;S.proCard='';S.group='全部';S.domain='全部';S.priority='all';S.pending=false;S.page=1;S.q='';$('search').value='';$('sidebar').classList.remove('open');if(jump){const cs=D.cards.filter(c=>!c.mergedInto&&c.cat===view);S.page=Math.floor(cs.findIndex(c=>c.id===jump)/12)+1}render();if(jump)requestAnimationFrame(()=>$('card-'+jump)?.scrollIntoView({behavior:'auto'}));else window.scrollTo({top:0,behavior:'auto'})}
function titleFor(){return META[S.view]?.name||({home:'背诵总览',relations:'申论八组关系',shspeeches:'上海工作重要论述',leadership:'长期执政的领导力',cdbtrack:'国开行考试主线',shtrack:'上海选调考试主线',library:'资料总目录',recite:'直接背 · 必背材料',audit:'国开行逐卷核对',calc:'财务计算专题',proindex:'专业题卷与知识关联',last:'综合速记表',quiz:'专项自测',stars:'我的收藏',errata:'口径辨析',sources:'资料依据',search:'全库搜索',newsfull:'经济金融时政全文',roadmap:'系统更新方案',exams:'题卷考点索引'})[S.view]||'讲义'}

function home(){
 const n=k=>D.cards.filter(c=>!c.mergedInto&&(c.cat===k||c.categoryTags?.includes(k))).length;
 const groupButton=(k,g,t)=>`<button class="chip" data-course="${k}" data-setgroup="${g}">${t}</button>`;
 const module=k=>`<button class="module" data-nav="${k}"><span class="module-code">${n(k)} 张记忆卡</span><h3>${META[k].name}</h3><p>${META[k].short||META[k].desc}</p></button>`;
 return `<section class="recite-priority"><h2>申论关系与重要论述</h2><button class="secondary" data-nav="relations">八组关系：主次、机制、条件与成效 →</button><div class="track-actions"><button class="secondary" data-nav="shspeeches">习近平重要论述 · 陈吉宁讲话 →</button><button class="chip" data-nav="leadership">长期执政的领导力 →</button><button class="chip" data-course="H" data-domain="国开行">国开行定位、行史、文化 →</button></div><p>背景与时间 → 核心内容 → 必背表述 → 易考与易混。来源与原题定位在每卡底部展开。</p></section><section class="exam-launch"><h2>按考试内容复习</h2><div class="exam-two"><button data-nav="cdbtrack"><b>国开行</b><span>英语 · EPI · 专业与计算 · 行史时政 · 综合写作</span></button><button data-nav="shtrack"><b>上海选调</b><span>政治理论 · 行测与科学推理 · 市情 · 申论</span></button></div><div class="track-actions"><button class="secondary" data-recite="全部">各章知识 · 直接背</button><button class="chip" data-nav="library">975份资料总目录</button></div></section><section class="recite-launch"><p class="eyebrow">不用找目录 · 打开就能背</p><h2>先背这里</h2><div class="track-actions" style="margin-bottom:16px"><button class="secondary" data-recite="资料分析">资料分析 · 18组常用公式 →</button><button class="chip" data-nav="W">国开申论 · 按主题背结构</button><button class="chip" data-nav="S">上海申论 · 按主题背结构</button></div><div class="recite-launch-grid">${[['新增','国开专业与申论精要','定义、机制、主题与论证'],['F','金融必背','定义、风险与金融计算'],['E','经济必背','理论、公式与易混点'],['A','会计财管','会计分录、年金与NPV'],['W','国开申论','主题段落与常用论据'],['S','上海申论','城市、创新与治理素材']].map(([k,t,desc])=>`<button data-recite="${k}"><b>${t}</b><span>${desc}</span><em>直接背 →</em></button>`).join('')}</div><div class="track-actions" style="margin-top:16px"><button class="chip" data-recite="H">行史行况与上海市情</button><button class="chip" data-recite="T">金融时政</button><button class="chip" data-recite="N">通用时政</button><button class="chip" data-recite="C">科学推理</button></div></section><section class="hero"><p class="eyebrow">关键词 · 逻辑链 · 成段素材 · 范文精读</p><div class="hero-top"><div><h1>国开行与上海选调<br>背诵资料</h1><p>先记核心表达，再记逻辑与完整段落。<br>详解和出处折叠，需要时展开。</p></div><div class="stamp">申论背诵版<br>2026年10月28日</div></div></section><div class="stats"><div class="stat"><b>${D.cards.filter(c=>c.essay?.teaching).length}</b><span>申论主题与结构</span></div><div class="stat"><b>6</b><span>完整教学范文</span></div><div class="stat"><b>36</b><span>范文精读段落</span></div><div class="stat"><b>${D.cards.filter(c=>!c.mergedInto).length}</b><span>全库记忆卡</span></div></div><div class="dash-grid active-tracks">${['W','S'].map(k=>{const g=D.essayGuides[k];return `<section class="plan-panel essay-home-panel"><p class="eyebrow">${k==='W'?'国家战略 · 开发性金融':'人民城市 · 创新治理'}</p><h2 class="panel-title">${g.title}</h2><p class="home-recitation">${g.core}</p><div class="memory-keywords">${g.words.map(t=>'<span>'+t+'</span>').join('')}</div><div class="track-actions"><button class="secondary" data-nav="${k}">进入素材库 →</button>${groupButton(k,'常用论据','名言与常用论据')}${groupButton(k,'主题素材','主题素材')}${groupButton(k,'句式积累','句式积累')}${groupButton(k,'整篇范文','范文精读')}</div></section>`}).join('')}</div><section class="memory-note"><b>申论素材的四层记忆</b><p>一句总括：记住主题判断。关键词：记住并列要点。完整段落：记住观点与机制。范文精读：积累表达，理解段落如何支撑全篇。</p><div class="memory-legend"><span><i class="legend-blue"></i>整理表达</span><span><i class="legend-green"></i>规范名称</span><span><i class="legend-amber"></i>时间或条件</span></div></section><div class="section-line"><h2>知识与时政速记</h2><span>默认要点置前，完整说明折叠</span></div><div class="module-grid">${['K','C','H','T','N'].map(module).join('')}</div><section class="document-panel calculation-highlight"><div><h2>年金 · NPV · YTM · PE</h2><p>系数、公式、时间轴和易错条件放在一起记，数值可离线验算。</p></div><button class="secondary" data-nav="calc">财务计算专题 →</button></section><div class="section-line"><h2>共用专业知识</h2></div><div class="module-grid">${['E','F','A','G','M'].map(module).join('')}</div><details class="legacy-wrap"><summary>原文、题卷、出处与后续备考</summary><div class="track-actions"><button class="chip" data-nav="newsfull">时政Word全文与全部配图</button><button class="chip" data-nav="exams">题卷索引</button><button class="chip" data-nav="sources">出处与依据</button></div><div class="dash-grid">${D.legacyHome}</div></details>`
}
function filtered(){
 let a=D.cards.filter(c=>!c.mergedInto);if(META[S.view])a=a.filter(c=>(c.cat===S.view||c.categoryTags?.includes(S.view)));if(S.view==='stars')a=a.filter(c=>S.stars.has(c.id));
 if(S.domain!=='全部')a=a.filter(c=>c.domain===S.domain);
 if(S.q){const terms=S.q.trim().toLowerCase().split(/\s+/).map(t=>({pa:'p/a',pf:'p/f',fa:'f/a',fp:'f/p',ap:'a/p',af:'a/f',pe:'p/e',pb:'p/b'})[t]||t);a=a.filter(c=>terms.every(t=>(c.id+' '+c.title+' '+c.body+' '+(c.searchAliases||[]).join(' ')+' '+c.group+' '+(c.domain||'')+' '+(META[c.cat]?.name||'')).toLowerCase().includes(t)))}
 if(S.group!=='全部')a=a.filter(c=>c.group===S.group);if(S.priority==='A')a=a.filter(c=>c.priority==='A');if(S.pending)a=a.filter(c=>!S.known.has(c.id));return a
}
function mathCard(c){const answerOpen=S.mathAnswers.has(c.id),solutionOpen=S.mathSolutions.has(c.id);let body=c.html;if(answerOpen)body=body.replace('data-math-answer="'+c.id+'"','data-math-answer="'+c.id+'" open');if(solutionOpen)body=body.replace('data-math-solution="'+c.id+'"','data-math-solution="'+c.id+'" open');return `<article class="card math-card ${S.recall?'recall-math':''} ${S.known.has(c.id)?'is-known':''}" id="card-${c.id}" data-testid="card-${c.id}"><div class="card-top"><div class="card-meta"><span class="card-id">${c.id}</span><span>${c.group}</span><span>教学讲义</span></div><button class="bookmark ${S.stars.has(c.id)?'on':''}" data-star="${c.id}" aria-label="${S.stars.has(c.id)?'取消收藏':'收藏'} ${c.id}" aria-pressed="${S.stars.has(c.id)}">${S.stars.has(c.id)?'★':'☆'}</button></div><h2>${esc(c.title)}</h2>${S.recall?'<p class="recall-prompt">练习视图：显示题干；知识点与方法暂时隐藏。</p>':''}${body}<div class="card-footer"><span class="provenance">公式条件 · 例题 · 分步推导</span><button class="known-btn ${S.known.has(c.id)?'on':''}" data-known="${c.id}" aria-label="${S.known.has(c.id)?'撤销掌握':'标记掌握'} ${c.id}" aria-pressed="${S.known.has(c.id)}">${S.known.has(c.id)?'✓ 已掌握':'○ 标记掌握'}</button></div></article>`}

function card(c){
 const reveal=!S.recall||S.revealed.has(c.id),essay=!!c.essay;
 const cues=(c.essay?.keywords||c.memory?.keywords||[]).map(t=>'<span>'+esc(t)+'</span>').join('');
 return `<article class="card ${essay?'essay-card':'memory-card'} ${S.known.has(c.id)?'is-known':''}" id="card-${c.id}" data-testid="card-${c.id}"><div class="card-top"><div class="card-meta"><span class="card-id">${c.id}</span><span>${esc(META[c.cat].name)} · ${esc(c.group)}</span><span class="memory-kind">${essay?esc(c.essay.label||'整理表达'):'记忆卡'}</span></div><button class="bookmark ${S.stars.has(c.id)?'on':''}" data-star="${c.id}" aria-label="${S.stars.has(c.id)?'取消收藏':'收藏'} ${c.id}" aria-pressed="${S.stars.has(c.id)}">${S.stars.has(c.id)?'★':'☆'}</button></div><h2>${esc(c.title)}</h2>${reveal?`<div class="prose">${memoryContent(c)}</div>`:`<div class="memory-keywords">${cues||'<span>'+esc(c.title)+'</span>'}</div><p class="recall-prompt">先回忆关键词、逻辑和完整表达，再展开核对。</p><button class="reveal" data-reveal="${c.id}">展开背诵材料 ↓</button>`}<div class="card-footer">${sourceFold(c)}<button class="known-btn ${S.known.has(c.id)?'on':''}" data-known="${c.id}" aria-label="${S.known.has(c.id)?'撤销掌握':'标记掌握'} ${c.id}" aria-pressed="${S.known.has(c.id)}">${S.known.has(c.id)?'✓ 已掌握':'○ 标记掌握'}</button></div></article>`
}
function listing(){
 const m=META[S.view],arr=filtered();S.page=Math.max(1,Math.min(S.page,Math.ceil(arr.length/12)||1));const page=arr.slice((S.page-1)*12,S.page*12);
 const gs=m?[...new Set(D.cards.filter(c=>(c.cat===S.view||c.categoryTags?.includes(S.view))&&(S.domain==='全部'||c.domain===S.domain)).map(c=>c.group))]:[];
 const related=S.view==='K'?'<button class="chip" data-course="H" data-domain="国开行">国开行行史行况</button><button class="chip" data-nav="T">金融时政</button>':S.view==='S'?'<button class="chip" data-course="H" data-domain="上海">上海市情</button><button class="chip" data-nav="C">科学推理</button><button class="chip" data-nav="N">通用时政</button>':S.view==='T'||S.view==='N'?'<button class="chip" data-nav="'+(S.view==='T'?'N':'T')+'">'+(S.view==='T'?'通用时政':'金融时政')+'</button><button class="chip" data-nav="newsfull">Word原文全文</button>':'';
 return `<section class="chapter-head"><p class="eyebrow">${m?.en||(S.view==='stars'?'YOUR COLLECTION':'SEARCH RESULTS')}</p><h1>${esc(titleFor())}</h1><p>${m?.desc||(S.view==='stars'?'收藏易错或反复忘记的点。点星标取消收藏，进度仅保存在当前浏览器。':`在全部${D.cards.length}条知识中搜索「${esc(S.q)}」，输入编号可定位。多个关键词以空格分开。`)}</p>${related?'<div class="track-actions">'+related+'</div>':''}</section>${knowledgeGuide()}${essayOverview()}${professionalIntro()}${scopeFilters()}${gs.length?`<div class="filters"><span class="small-copy">按知识点</span>${['全部',...gs].map(g=>`<button class="chip ${S.group===g?'selected':''}" data-group="${esc(g)}">${esc(g)}</button>`).join('')}</div>`:''}
 <div class="memory-mode-controls" aria-label="阅读层次">${[['brief','速背卡'],['memory','背诵素材'],['full','完整讲解']].map(([v,t])=>`<button class="chip ${S.readMode===v?'selected':''}" data-readmode="${v}">${t}</button>`).join('')}<span>要点置前 · 解释与出处折叠</span></div><div class="reader-toolbar"><div class="toolbar-left"><label class="check"><input type="checkbox" id="pendingCheck" ${S.pending?'checked':''}>只看待复习</label><label class="check"><input type="checkbox" id="recallCheck" ${S.recall?'checked':''}>遮挡背诵</label></div><div class="toolbar-right"><span>${arr.length} 个考点</span><span>第 ${S.page} / ${Math.ceil(arr.length/12)||1} 页</span></div></div>
 ${S.view==='M'?'<div class="math-view-tools"><button class="chip" data-math-batch="answers">展开本页答案</button><button class="chip" data-math-batch="solutions">展开本页解析</button><button class="chip" data-math-batch="close">收起本页答案与解析</button></div>':''}
 <div class="reader-grid ${arr.length?'':'no-index'}"><section>${page.map(card).join('')||'<div class="empty">这里暂时没有考点。<br>试试更换关键词，或关闭筛选。</div>'}${arr.length>12?`<div class="pager"><button data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><span>${S.page} / ${Math.ceil(arr.length/12)}</span><button data-page="${S.page+1}" ${S.page*12>=arr.length?'disabled':''}>下一页</button></div>`:''}</section>${arr.length?`<aside class="mini-index" aria-label="本章考点索引"><div class="index-label">本章索引 / ${arr.length}</div>${arr.map(c=>`<button class="index-item" data-jump="${c.id}"><b>${c.id}</b>${esc(c.title)}</button>`).join('')}</aside>`:''}</div>`
}
function quizItems(){return D.quiz.filter(q=>S.group==='全部'||q.track===S.group)}
function quiz(){
 const qs=quizItems(),tracks=['全部','国开行','上海选调申论','科学推理','行史市情','金融时政','通用时政','共用基础','会计与财务','财务计算','经济金融'];
 return `<section class="chapter-head"><p class="eyebrow">LEARN → TEST → REVIEW</p><h1>专项自测</h1><p>${D.quiz.length}题，按重组后的知识章节分组。先独立作答，再展开答案并回查卡片。</p></section><div class="filters">${tracks.map(g=>`<button class="chip ${S.group===g?'selected':''}" data-group="${g}">${g}</button>`).join('')}</div><div class="reader-toolbar"><span>${qs.length}道题</span><button class="secondary" id="quizToggle">展开全部答案</button></div><div style="max-width:900px">${qs.map(q=>`<article class="card quiz"><div class="card-id">${q.id} / ${esc(q.track)}</div><h2>${esc(q.q)}</h2><details><summary>答案与解析</summary><div class="quiz-answer">${q.html}</div></details></article>`).join('')}</div>`
}
function questionIndex(){return `<details class="question-index"><summary>旧题对应与2026核对索引 · ${D.questionMappings.length}项</summary><p class="small-copy">PDF页码为文件页码；题库中的“真题”“回忆版”是资料自身标签，未据此确认官方命题来源。未取得官方原文的线索保留在索引，不混入标准表述。</p><div class="table-wrap"><table><thead><tr><th>原资料与位置</th><th>原题内容</th><th>讲义位置</th><th>核对与更新</th></tr></thead><tbody>${D.questionMappings.map(x=>`<tr><td><b>${esc(x.source)}</b> · PDF ${esc(x.page)}<br>${esc(x.question)}<details><summary>文件名</summary>${esc(x.file)}</details></td><td>${esc(x.topic)}</td><td>${esc(x.cards)}</td><td>${esc(x.note)}</td></tr>`).join('')}</tbody></table></div></details>`}

function sources(){return `<section class="chapter-head"><p class="eyebrow">SOURCES AND EDITIONS</p><h1>资料依据</h1><p>${esc(D.updateNote)}</p></section><div class="card"><div class="prose"><p>资料分为官方公开信息、用户原文、历史文化手册与题卷，以及明确标注的自编训练。原文、历史数字和当前核对口径分别呈现。</p><p>经济金融时政Word全文含52事项、8组易混口径和6幅原始配图。国开行资料按PDF页定位；题卷标题沿用用户资料名称，不将资料标题冒充官方真题认证。</p></div></div>${questionIndex()}<div class="section-line"><h2>${D.sources.length}组资料来源</h2></div>${D.sources.map(s=>`<div class="source-row" id="source-${s.id}"><button class="card-id" data-source="${s.id}">${s.id}</button><div class="source-text">${s.html}</div></div>`).join('')}`}


function newsfull(){
 return `<section class="chapter-head"><p class="eyebrow">FULL DOCUMENT / OFFLINE INCLUDED</p><h1>中国经济金融时政速记 · 原文全文</h1><p>52事项、8组辨析、135主文段落及6幅原始配图完整保留。全文沿用原次序；考点卡片已分别编入金融时政、通用时政。可用浏览器查找和“打印本章”。</p></section><div class="reader-toolbar"><div class="track-actions"><button class="secondary" data-nav="T">金融时政</button><button class="secondary" data-nav="N">通用时政</button></div><a href="#local-reference">打开归档Word</a></div><div class="reader-grid"><article class="card source-document"><div class="prose">${D.fullNews.html}</div></article><aside class="mini-index"><div class="index-label">全文目录 / 60项</div>${D.fullNews.toc.map((x,i)=>{const c=D.cards.find(c=>c.id==='NEWS'+String(i+1).padStart(3,'0'));return `<button class="index-item" data-docjump="doc-block-${x.index}"><b>${c?.cat==='T'?'金融时政':'通用时政'}</b>${esc(x.title)}</button>`}).join('')}</aside></div>`
}
function roadmap(){return `<section class="chapter-head"><p class="eyebrow">SYSTEM UPDATE / IMPLEMENTED</p><h1>系统更新方案</h1><p>把资料内容、知识讲解、考法、训练和出处组成完整学习流程。</p></section><article class="card"><div class="prose">${D.plan}</div></article>`}
function exams(){
 const rows=D.examEvidence||[];
 return `<section class="chapter-head"><p class="eyebrow">EXAM EVIDENCE</p><h1>题卷考点索引</h1><p>国开行历年题卷与上海中公、津仕模拟卷按PDF页、题号和知识卡片连接。题卷名称沿用归档标签；图形题回原卷看图。</p></section><div class="track-actions"><button class="chip" data-sectionjump="cdb-evidence">国开行历年卷</button><button class="chip" data-sectionjump="shanghai-evidence">上海模拟卷</button></div><section id="cdb-evidence"><h2>国开行历年题卷</h2><article class="card"><div class="prose"><p>金融与EPI的原卷题解在国开行专题；行史文化问法来自文化手册与指南，在行史行况章集中学习。标注“自编考法”的题目不冒充某年考题。</p></div></article>${rows.map(row=>`<article class="card"><div class="card-id">${esc(row.year)} / ${row.pages}个PDF页</div><h2>${esc(row.title)}</h2><div class="prose"><p>${esc(row.method)}</p>${row.hits.map(h=>`<details><summary>PDF ${h.page} · ${esc(h.topic)}</summary><p>${esc(h.snippet)}</p></details>`).join('')}</div><div class="card-footer"><button class="cite" data-source="CDBY${row.year}">打开来源 CDBY${row.year}</button></div></article>`).join('')}</section><section id="shanghai-evidence">${mockIndex()}</section>`
}
function renderLegacy(){nav();$('crumbText').textContent=titleFor();$('printBtn').textContent=S.view==='newsfull'?'打印全文':S.view==='calc'?'打印计算结果':S.readMode==='brief'?'打印速背卡':S.readMode==='full'?'打印完整讲解':'打印背诵资料';$('main').innerHTML=S.view==='home'?home():S.view==='relations'?relationReader():S.view==='shspeeches'?speechSpecial():S.view==='leadership'?leadershipSpecial():['cdbtrack','shtrack'].includes(S.view)?examDashboard(S.view):S.view==='library'?libraryReader():S.view==='recite'?reciteShelf():S.view==='audit'?auditReader():S.view==='calc'?calculatorView():S.view==='proindex'?professionalIndex():S.view==='newsfull'?newsfull():S.view==='roadmap'?roadmap():S.view==='exams'?exams():S.view==='quiz'?quiz():S.view==='sources'?sources():S.view==='last'?`<section class="chapter-head"><p class="eyebrow">QUICK REFERENCE</p><h1>综合速记表</h1><p>国开行与上海选调优先，通用基础和邮储农行随后。</p></section><article class="card"><div class="prose">${D.last}</div></article>`:S.view==='errata'?`<section class="chapter-head"><p class="eyebrow">DISTINCTIONS</p><h1>口径辨析</h1><p>历史版本、当前数据、公式条件和题干范围分别核对。</p></section><article class="card"><div class="prose">${D.errata}</div></article>`:listing();$('main').insertAdjacentHTML('beforeend',`<footer class="footnote">国开行与上海选调自习室<br>${esc(D.updateNote)}<span class="footer-tip"> Ctrl K 搜索 · 收藏与掌握记录保存在当前浏览器。</span></footer>`)}

function openSource(id){const s=D.sources.find(x=>x.id===id);if(!s)return;$('modalRoot').innerHTML=`<div class="modal-backdrop" id="sourceBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="资料依据 ${id}"><div class="modal-top"><span>资料与核对依据 / ${id}</span><button class="icon-btn" id="closeSource" aria-label="关闭出处">关闭 ✕</button></div><div class="prose">${s.html}</div><p class="small-copy">官方链接需要联网。正文可继续离线阅读。历史报表须区分报告期、数据口径和披露日期。</p></section></div>`;$('closeSource').focus()}
function printChapter(){let title=titleFor(),body='';if(META[S.view]||S.view==='stars'||S.view==='search')body=filtered().map(c=>`<section class="print-card"><small>${c.id} / ${esc(c.domain||'')} / ${esc(c.group)}</small><h2>${esc(c.title)}</h2><div class="prose">${memoryContent(c,true)}</div></section>`).join('');else if(S.view==='relations'){body=relationReader()}else if(S.view==='shspeeches'){body=speechSpecial()}else if(S.view==='leadership'){body=leadershipSpecial()}else if(['cdbtrack','shtrack'].includes(S.view)){body=examDashboard(S.view)}else if(S.view==='library'){title+='（当前页）';body=libraryReader()}else if(S.view==='recite'){title+='（当前页）';body=reciteShelf()}else if(S.view==='audit'){title+='（当前页）';body=auditReader()}else if(S.view==='calc')body='<div class="prose">'+$('calcResult').innerHTML+'</div>';else if(S.view==='proindex'){title+='（当前页）';body=professionalIndex()}else if(S.view==='newsfull')body='<div class="prose">'+D.fullNews.html+'</div>';else if(S.view==='roadmap')body='<div class="prose">'+D.plan+'</div>';else if(S.view==='exams')body=exams();else if(S.view==='quiz')body=quizItems().map(q=>`<section class="print-card"><h2>${q.id} ${esc(q.q)}</h2><div>${q.html}</div></section>`).join('');else if(S.view==='sources')body=sources();else body='<div class="prose">'+(S.view==='errata'?D.errata:D.last)+'</div>';$('printArea').innerHTML=`<h1>${esc(title)}</h1><p class="small-copy">${esc(D.updateNote)}</p>${body}`;window.print()}
document.addEventListener('click',e=>{if(shAction(e))return;if(portableClick(e))return;const b=e.target.closest('button');if(!b){if(e.target.id==='sourceBackdrop')$('modalRoot').innerHTML='';return}if(b.dataset.libsearch){S.libQuery=$('librarySearch').value;S.page=1;render();return}if(b.dataset.recite){go('recite');S.group=b.dataset.recite;S.readMode='memory';save();render();return}if(b.dataset.readmode){S.readMode=b.dataset.readmode;save();render();return}if(b.id==='focusBtn'){S.focus=!S.focus;document.documentElement.classList.toggle('focus-reader',S.focus);b.textContent=S.focus?'退出专注':'专注阅读';save();return}if(b.dataset.finmode){S.finMode=b.dataset.finmode;render();return}if(b.dataset.fincompute){computeFinance(b.dataset.fincompute);return}if(b.dataset.prosubject){go('proindex');S.group=META[b.dataset.prosubject].name;render();return}if(b.dataset.procard){go('proindex');S.proCard=b.dataset.procard;render();return}if(b.dataset.proclear){S.proCard='';S.page=1;render();return}if(b.dataset.studyBatch){if(b.dataset.studyBatch==='open')S.readMode='full';const cs=filtered().slice((S.page-1)*12,S.page*12);for(const c of cs){if(b.dataset.studyBatch==='open')S.studyAnswers.add(c.id);else S.studyAnswers.delete(c.id)}render();return}if(b.dataset.mathBatch){S.readMode='full';const cs=filtered().slice((S.page-1)*12,S.page*12).filter(c=>c.cat==='M');for(const c of cs){if(b.dataset.mathBatch==='close'){S.mathAnswers.delete(c.id);S.mathSolutions.delete(c.id)}else if(b.dataset.mathBatch==='answers')S.mathAnswers.add(c.id);else S.mathSolutions.add(c.id)}render();return}if(b.dataset.docjump){$(''+b.dataset.docjump)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.cardlink){const cardId=D.readingAliases?.[b.dataset.cardlink]||b.dataset.cardlink;const c=D.cards.find(c=>c.id===cardId);if(c)go(c.cat,c.id);return}if(b.dataset.sectionjump){$(b.dataset.sectionjump)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.course){go(b.dataset.course);S.domain=b.dataset.domain||'全部';S.group=b.dataset.setgroup||'全部';render();return}if(b.dataset.domain){S.domain=b.dataset.domain;S.group='全部';S.page=1;render();return}if(b.dataset.bank){go('H');S.domain=b.dataset.bank;render();return}if(b.dataset.nav){go(b.dataset.nav);return}if(b.dataset.group){S.group=b.dataset.group;S.page=1;render();return}if(b.dataset.page){S.page=Number(b.dataset.page);render();window.scrollTo({top:0,behavior:'auto'});return}if(b.dataset.jump){const id=b.dataset.jump;const arr=filtered();S.page=Math.floor(arr.findIndex(c=>c.id===id)/12)+1;render();requestAnimationFrame(()=>$('card-'+id)?.scrollIntoView({behavior:'auto'}));return}if(b.dataset.source){openSource(b.dataset.source);return}if(b.dataset.reveal){S.revealed.add(b.dataset.reveal);const c=D.cards.find(x=>x.id===b.dataset.reveal);$('card-'+c.id).outerHTML=card(c);return}if(b.dataset.star){const id=b.dataset.star;S.stars.has(id)?S.stars.delete(id):S.stars.add(id);save();if(['stars','recite','shspeeches','leadership'].includes(S.view))render();else{const c=D.cards.find(x=>x.id===id);$('card-'+id).outerHTML=card(c);nav()}return}if(b.dataset.known){const id=b.dataset.known;S.known.has(id)?S.known.delete(id):S.known.add(id);save();if(S.pending||S.view==='recite')render();else{$('card-'+id).outerHTML=card(D.cards.find(x=>x.id===id))}return}if(b.id==='priorityBtn'){S.priority=S.priority==='A'?'all':'A';S.page=1;render()}if(b.id==='menuBtn')$('sidebar').classList.toggle('open');if(b.id==='backTop')window.scrollTo({top:0,behavior:'smooth'});if(b.id==='closeSource')$('modalRoot').innerHTML='';if(b.id==='larger'||b.id==='smaller'){S.font=Math.max(15,Math.min(22,S.font+(b.id==='larger'?1:-1)));document.documentElement.style.setProperty('--text',S.font+'px');save();toast('正文字号 '+S.font+'px')}if(b.id==='printBtn')printChapter();if(b.id==='quizToggle'){const ds=[...document.querySelectorAll('.quiz details')];const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);b.textContent=open?'收起全部答案':'展开全部答案'}});
document.addEventListener('toggle',e=>{const t=e.target;if(t.dataset?.studyAnswer){t.open?S.studyAnswers.add(t.dataset.studyAnswer):S.studyAnswers.delete(t.dataset.studyAnswer)}if(t.dataset?.mathAnswer){t.open?S.mathAnswers.add(t.dataset.mathAnswer):S.mathAnswers.delete(t.dataset.mathAnswer)}if(t.dataset?.mathSolution){t.open?S.mathSolutions.add(t.dataset.mathSolution):S.mathSolutions.delete(t.dataset.mathSolution)}},true);
document.addEventListener('change',e=>{if(e.target.id==='pendingCheck'){S.pending=e.target.checked;S.page=1;render()}if(e.target.id==='recallCheck'){S.recall=e.target.checked;S.revealed.clear();render()}});
let searchTimer;$('search').addEventListener('input',e=>{const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{S.q=value;S.view=value.trim()?'portable-search':'home';S.page=1;S.group='全部';S.domain='全部';S.priority='all';S.pending=false;render();window.scrollTo({top:0,behavior:'auto'})},150)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus()}if(e.key==='Escape'){$('modalRoot').innerHTML='';$('sidebar').classList.remove('open');$('search').blur()}});
function bodyFor(c,print=false){if(c.normative)return normativeBody(c);
 let out=c.foundationHtml||c.readingHtml||c.html;
 if(c.cat==='M'&&print)return c.printHtml||c.html;
 if(c.foundationHtml)out='<section class="study-foundation"><h3>基础知识与原有例题</h3>'+out+'</section>';
 if(c.enrichment){const e=c.enrichment;out+=`<section class="study-focus"><h3>条件与解题方法</h3><p>${esc(e.focus)}</p><div class="formula-box">${esc(e.formula)}</div></section><section class="practice-stem"><h3>配套练习 · 整理改编</h3><p>${esc(e.question)}</p></section><details class="training-answer" data-study-answer="${c.id}" ${print||S.studyAnswers.has(c.id)?'open':''}><summary>答案、推导与易错点</summary><p>${esc(e.answer)}</p><p class="study-trap"><b>易错提醒：</b>${esc(e.trap)}</p></details>`}
 if(c.relatedProfessional?.length)out+=`<div class="related-knowledge">系统讲解：${c.relatedProfessional.map(id=>print?esc(id):`<button class="chip" data-cardlink="${id}">${id} ${esc(D.cards.find(x=>x.id===id)?.title||'')}</button>`).join(' ')}</div>`;
 if(c.examLinks?.length){const es=c.examLinks.slice(0,3).map(id=>D.professionalEvidence.find(x=>x.id===id));out+=`<details class="professional-origins" ${print?'open':''}><summary>原卷考法与整理提示 · ${c.examLinks.length}项</summary>${es.map(e=>`<p><b>${esc(e.kind)} · ${esc(e.source)}</b> · PDF ${e.page} · ${esc(e.question)}<br>${esc(e.review)}</p>`).join('')}${print?'':`<button class="chip" data-procard="${c.id}">查看本卡全部题卷关联 →</button>`}</details>`}
 if(c.lectureRoute){const r=c.lectureRoute;out+=`<details class="professional-origins"><summary>讲义定位 · ${r.source} / PDF ${r.page}</summary><p>${esc(r.file)} · 关键词“${esc(r.term)}”</p><a href="${esc(r.href)}#page=${r.page}" target="_blank" rel="noopener">打开讲义相应页</a></details>`}
 out=out.replace(/<details class="training-answer"(?![^>]*data-study-answer)/g,`<details class="training-answer" data-study-answer="${c.id}" ${print||S.studyAnswers.has(c.id)?'open':''}`);
 return print?out.replace(/<details(?![^>]*\bopen\b)/g,'<details open'):out
}
function professionalIntro(){
 if(!D.subjectGuides?.[S.view])return '';
 return `<div class="compact-study-tools">${['A','F'].includes(S.view)?'<button class="chip" data-nav="calc">年金 / NPV / YTM / PE验算</button>':''}<button class="secondary" data-recite="${S.view}">本章必背 · 直接展开</button><button class="chip" data-readmode="full">详解与例题</button><button class="chip secondary-source-link" data-prosubject="${S.view}">题卷关联</button></div>`
}
function professionalIndex(){
 const all=D.professionalEvidence,cat=['A','E','F','G'].find(k=>META[k].name===S.group);
 let arr=all.filter(e=>(!cat||e.cats.includes(cat))&&(!S.proCard||e.cards.includes(S.proCard)));
 S.page=Math.max(1,Math.min(S.page,Math.ceil(arr.length/12)||1));const page=arr.slice((S.page-1)*12,S.page*12);
 return `<section class="chapter-head"><p class="eyebrow">PROFESSIONAL / SOURCE TO KNOWLEDGE</p><h1>专业题卷与知识关联</h1><p>三套机构专业卷共185题分段提取，其中${D.professionalCoverage.mockQuestionsReviewed}题作专业定向复核，另连接${D.professionalCoverage.yearEvidence}组历年题卷定位。不同资料可能重复题材，数量不代表真实考频。原资料标签不等于官方试卷认证。</p></section><div class="filters">${['全部',...['A','E','F','G'].map(k=>META[k].name)].map(t=>`<button class="chip ${S.group===t?'selected':''}" data-group="${esc(t)}">${esc(t)}</button>`).join('')}${S.proCard?`<button class="chip selected" data-proclear="yes">仅${esc(S.proCard)} · 点击清除</button>`:''}</div><div class="reader-toolbar"><span>${arr.length}组关联 · 第${S.page}/${Math.ceil(arr.length/12)||1}页</span></div>${page.map(e=>`<article class="card professional-evidence"><div class="card-id">${esc(e.kind)} / ${esc(e.source)} / PDF ${e.page}</div><h2>${esc(e.file)} · ${esc(e.question)}</h2><div class="prose"><h3>整理解释与使用条件</h3><p>${esc(e.review)}</p>${e.raw?`<details class="raw-question"><summary>查看原题与原答案 · 按资料保留</summary><p class="small-copy">历史数据、旧规则和印刷答案先看上面的整理解释；原题内容仅作为回查依据。</p><div class="raw-question-text">${esc(e.raw)}</div></details>`:''}</div><div class="track-actions">${e.cards.map(id=>`<button class="chip" data-cardlink="${id}">${id} ${esc(D.cards.find(c=>c.id===id)?.title||'')}</button>`).join('')}<a class="source-link" href="${esc(e.href)}#page=${e.page}" target="_blank" rel="noopener">打开原卷PDF ${e.page} →</a></div></article>`).join('')||'<div class="empty">当前筛选没有题卷关联，请清除单卡或章节筛选。</div>'}${arr.length>12?`<div class="pager"><button data-page="${S.page-1}" ${S.page===1?'disabled':''}>上一页</button><span>${S.page} / ${Math.ceil(arr.length/12)}</span><button data-page="${S.page+1}" ${S.page*12>=arr.length?'disabled':''}>下一页</button></div>`:''}`
}

const FinanceMath={
 pa(i,n){return Math.abs(i)<1e-12?n:-Math.expm1(-n*Math.log1p(i))/i},
 fa(i,n){return Math.abs(i)<1e-12?n:Math.expm1(n*Math.log1p(i))/i},
 npv(i,cfs){return cfs.reduce((v,c,t)=>v+c/Math.pow(1+i,t),0)},
 bondPrice(r,c,f,n){return c*this.pa(r,n)+f/Math.pow(1+r,n)},
 solvePrice(price,c,f,n){let lo=-0.999999,hi=1;while(this.bondPrice(hi,c,f,n)>price&&hi<1e6)hi=hi*2+1;for(let k=0;k<160;k++){const mid=(lo+hi)/2;if(this.bondPrice(mid,c,f,n)>price)lo=mid;else hi=mid}return (lo+hi)/2},
 irr(cfs){if(!(cfs[0]<0&&cfs.slice(1).every(c=>c>=0)&&cfs.slice(1).some(c=>c>0)))return null;let lo=-0.999999,hi=1;while(this.npv(hi,cfs)>0&&hi<1e6)hi=hi*2+1;if(this.npv(hi,cfs)>0)return null;for(let k=0;k<160;k++){const mid=(lo+hi)/2;if(this.npv(mid,cfs)>0)lo=mid;else hi=mid}return (lo+hi)/2}
};
const fnum=(n,d=6)=>Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:0}):'超出可计算范围';
const fpct=n=>fnum(n*100,6)+'%';
function finInput(id,label,value,type='number',help=''){return `<label class="fin-field" for="${id}"><span>${label}</span><input id="${id}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}">${help?'<small>'+help+'</small>':''}</label>`}
function calculatorView(){
 const mode=S.finMode||'annuity';let form='',scope='',links='';
 if(mode==='annuity'){
  scope='i是每期利率，n是期数；先确定目标/已知。金额单位自行统一，计算结果沿用同一单位。';
  form=`<label class="fin-field" for="finFactor"><span>目标 / 已知系数</span><select id="finFactor"><option value="pa">P/A：已知每期A，求现值P</option><option value="fa">F/A：已知每期A，求终值F</option><option value="pf">P/F：已知终点F，求现值P</option><option value="fp">F/P：已知现值P，求终值F</option><option value="ap">A/P：已知现值P，求每期A</option><option value="af">A/F：已知终值F，求每期A</option></select></label>${finInput('finAmount','已知金额',100)}${finInput('finRate','每期利率（%）',10)}${finInput('finPeriods','期数n',3)}<label class="fin-field" for="finTiming"><span>现金流时点（仅P/A或F/A生效）</span><select id="finTiming"><option value="ordinary">普通年金：每期期末</option><option value="due">预付年金：每期期初</option><option value="deferred">递延年金：仅用于P/A</option></select></label>${finInput('finDefer','递延m：第一笔在m+1期末',2,'number','仅递延P/A使用；第3期首笔则m＝2。')}`;
  links=['A46','A47','A48','A51','A52'];
 }else if(mode==='npv'){
  scope='等间隔现金流按t0、t1、t2……输入；正为流入、负为流出。终点回收合并入终点金额。IRR工具仅自动处理初期流出、后续非负的常规序列。';
  form=`${finInput('finRate','每期折现率（%）',10)}<label class="fin-field fin-wide" for="finFlows"><span>现金流序列（首项发生在现在）</span><textarea id="finFlows" rows="3">-120, 50, 50, 80</textarea><small>逗号、空格或换行分隔；如−100,40,40,40。</small></label>`;links=['A49','A50','A13'];
 }else if(mode==='ytm'){
  scope='简化模型：结算日在付息日；输入全价，固定票息、到期还面值、无违约、税费或提前赎回。非付息日全价和分数期数需另按题设处理。';
  form=`${finInput('finPrice','债券当前全价P',95)}${finInput('finFace','到期面值F',100)}${finInput('finCoupon','年票面利率（%）',5)}${finInput('finYears','剩余年数',2)}<label class="fin-field" for="finFrequency"><span>每年付息次数m</span><select id="finFrequency"><option value="1">1：年付息</option><option value="2">2：半年付息</option><option value="4">4：季付息</option><option value="12">12：月付息</option></select></label>`;links=['F54','F55','F56','F58'];
 }else{
  scope='教学估值只做口径清晰的算术；PE使用正EPS才具有常规倍数比较意义。目标PE与当前EPS必须按题设匹配。';
  form=`${finInput('finStock','每股价格P',30)}${finInput('finEPS','每股收益EPS',2)}${finInput('finBVPS','每股净资产BVPS',10)}${finInput('finTargetPE','目标PE倍数',18)}`;links=['F57','A10','A15'];
 }
 return `<section class="chapter-head"><p class="eyebrow">FINANCIAL CALCULATIONS / OFFLINE</p><h1>财务计算专题</h1><p>先看时间轴与公式，再手算、验算。重点练年金系数、NPV、YTM和PE。</p></section><div class="filters">${[['annuity','年金与六个系数'],['npv','NPV与IRR'],['ytm','债券YTM'],['pe','PE与PB']].map(([id,t])=>`<button class="chip ${id===mode?'selected':''}" data-finmode="${id}">${t}</button>`).join('')}</div><article class="card"><div class="prose"><p class="calculation-scope">${scope}</p></div><div class="fin-form">${form}</div><div class="track-actions"><button class="secondary" data-fincompute="${mode}">计算并显示步骤</button>${links.map(id=>`<button class="chip" data-cardlink="${id}">${id} 讲解</button>`).join('')}</div><div id="calcResult" class="fin-result" aria-live="polite"><p>填写数据后计算。结果同时显示公式和步骤。</p></div></article><article class="card"><h2>手算检查顺序</h2><div class="prose"><ol><li>在时间轴上标出t0、首笔和末笔；分清单笔、多笔、期初、期末、递延。</li><li>统一每期利率、现金流间隔与期数。区分年名义和年有效利率。</li><li>年金按目标/已知选P/A、A/P等；债券将票息年金与本金单笔分开。</li><li>先估方向，再计算。正利率下，远期单笔现值较小；债券价格与YTM一般反向。</li><li>最后代回方程，并标注金额、百分比、每期或年化口径。</li></ol></div></article>`
}
function computeFinance(mode){
 const num=id=>{const v=Number($(id).value);if(!$(id).value.trim()||!Number.isFinite(v))throw Error('请填写有限数值。');return v};
 const grid=(h,rows)=>`<div class="table-wrap"><table><thead><tr>${h.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
 try{let html='';
  if(mode==='annuity'){
   const i=num('finRate')/100,n=num('finPeriods'),v=num('finAmount'),type=$('finFactor').value,timing=$('finTiming').value,m=timing==='deferred'&&type==='pa'?num('finDefer'):0;
   if(i<=-1||!Number.isInteger(n)||n<1||n>600)throw Error('每期利率须大于−100%，n须为1—600的整数。');
   const pa=FinanceMath.pa(i,n),fa=FinanceMath.fa(i,n);let factor=({pa,fa,pf:(1+i)**(-n),fp:(1+i)**n,ap:1/pa,af:1/fa})[type],adjust='普通期末/单笔口径';
   if(['pa','fa'].includes(type)&&timing==='due'){factor*=1+i;adjust='预付年金：普通系数×(1+i)'}
   if(['pa','fa'].includes(type)&&timing==='deferred'){
    if(type!=='pa')throw Error('递延项请使用P/A求今天现值；终值请明确终点后另按时间轴换算。');
    if(!Number.isInteger(m)||m<0||m>600)throw Error('递延m须为0—600整数。');factor*=(1+i)**(-m);adjust=`递延：首笔在${m+1}期末，普通P/A再折${m}期`;
   }
   const result=v*factor;if(!Number.isFinite(result))throw Error('数值超出稳定计算范围，请缩短期数或调整利率。');
   html=`<h2>结果：${fnum(result)}</h2><p>${esc(type.toUpperCase()[0]+'/'+type.toUpperCase()[1])}系数＝${fnum(factor,10)}；${adjust}。</p><div class="formula-box">${fnum(v)} × ${fnum(factor,10)} ＝ ${fnum(result)}</div>`+grid(['普通期末/单笔系数','数值'],[['P/A',fnum(pa,10)],['F/A',fnum(fa,10)],['P/F',fnum((1+i)**(-n),10)],['F/P',fnum((1+i)**n,10)],['A/P',fnum(1/pa,10)],['A/F',fnum(1/fa,10)]]);
  }else if(mode==='npv'){
   const i=num('finRate')/100,cfs=$('finFlows').value.replace(/−/g,'-').trim().split(/[\s,，;；]+/).map(Number);
   if(i<=-1||cfs.length<2||cfs.length>101||cfs.some(x=>!Number.isFinite(x)))throw Error('折现率须大于−100%，现金流输入2—101项有限数值。');
   const npv=FinanceMath.npv(i,cfs),irr=FinanceMath.irr(cfs);if(!Number.isFinite(npv))throw Error('数值超出计算范围。');
   html=`<h2>NPV：${fnum(npv)}</h2><p>各期现值相加；${npv>0?'按该现金流和折现率，净现值为正。':npv<0?'按该现金流和折现率，净现值为负。':'净现值为零。'}</p>`+grid(['t','现金流','折现因子','现值'],cfs.map((c,t)=>[t,fnum(c),fnum((1+i)**(-t),8),fnum(c/(1+i)**t)]))+`<p>常规序列IRR：${irr===null?'本工具不对此现金流自动报告唯一IRR；需另查多根或无根。':fpct(irr)+'；代回NPV≈'+fnum(FinanceMath.npv(irr,cfs),9)}</p>`;
  }else if(mode==='ytm'){
   const price=num('finPrice'),face=num('finFace'),coupon=num('finCoupon')/100,years=num('finYears'),m=Number($('finFrequency').value),N=years*m;
   if(price<=0||face<=0||coupon<0||!Number.isInteger(N)||N<1||N>600)throw Error('价格、面值须大于0，票面利率非负；年数×付息次数须为1—600整数。');
   const c=face*coupon/m,r=FinanceMath.solvePrice(price,c,face,N),apr=m*r,ear=(1+r)**m-1,pv=FinanceMath.bondPrice(r,c,face,N);
   html=`<h2>每期YTM：${fpct(r)}</h2>`+grid(['口径','计算结果'],[['每期票息',fnum(c)],['总付息期数',N],['名义年化YTM＝m×r',fpct(apr)],['有效年收益率＝(1+r)^m−1',fpct(ear)],['当期收益率＝年票息/价格',fpct(face*coupon/price)]])+`<div class="formula-box">${fnum(price)} ＝ ${fnum(c)}×(P/A,r,${N}) ＋ ${fnum(face)}×(P/F,r,${N})<br>代回现值＝${fnum(pv,9)}，残差＝${fnum(pv-price,9)}</div><p>每期利率是方程数值解。名义年化与有效年率均列出，按题目要求选择。</p>`;
  }else{
   const p=num('finStock'),eps=num('finEPS'),bv=num('finBVPS'),target=num('finTargetPE');if(p<0||target<0)throw Error('价格和目标PE倍数须为非负。');
   html='<h2>倍数与教学估值</h2>'+grid(['项目','结果'],[['PE＝P/EPS',eps>0?fnum(p/eps)+'倍':'EPS非正，不作常规正PE比较'],['PB＝P/BVPS',bv>0?fnum(p/bv)+'倍':'每股净资产非正，不作常规正PB比较'],['目标PE×EPS',eps>0?fnum(target*eps):'EPS非正，不按此常规倍数法估值']])+'<p>估值结果依题设数据和可比口径；不能将PE直接当保证回本年数。</p>';
  }
  $('calcResult').innerHTML=html;
 }catch(e){$('calcResult').innerHTML='<p class="calc-error" role="alert">'+esc(e.message)+'</p>'}
}

/* Portable reader: shares the existing D, cards, calculator and full reader. */
const PK='bank-study-2026-v2',PBK=PK+'-backup-before-portable';
let portableRaw=null,storageHealthy=true;
try{portableRaw=localStorage.getItem(PK);if(portableRaw!==null&&localStorage.getItem(PBK)===null)localStorage.setItem(PBK,portableRaw);if(portableRaw!==null){const x=JSON.parse(portableRaw);if(!x||Array.isArray(x)||typeof x!=='object')storageHealthy=false}}catch(e){storageHealthy=false}
const P=Object.assign({version:1,exam:'cdb',again:[],last:null,byExam:{},daily:{},reviewed:{},onlyUnknown:false},saved.portable||{});
P.again=new Set(Array.isArray(P.again)?P.again:[]);P.byExam=P.byExam||{};P.daily=P.daily||{};P.reviewed=P.reviewed||{};
if(!['cdb','sh'].includes(P.exam))P.exam='cdb';
const cardMap=new Map(D.cards.map(c=>[c.id,c]));
function learnKey(id){const cid=canonicalCardId(id);return cardMap.get(cid)?.learningKey||cid}

try{const bk=PK+'-backup-before-merge-20261029';if(portableRaw!==null&&localStorage.getItem(bk)===null)localStorage.setItem(bk,portableRaw)}catch(e){}
function citySession(s){if(!s||typeof s!=='object')return s;return {...s,ids:canonicalIds(s.ids),currentId:canonicalCardId(s.currentId)}}
P.last=citySession(P.last);for(const ex of Object.keys(P.byExam))P.byExam[ex]=citySession(P.byExam[ex]);
for(const key of Object.keys(P.daily))P.daily[key]=canonicalIds(P.daily[key]);
for(const [id,time] of Object.entries(P.reviewed)){const key=learnKey(id);P.reviewed[key]=Math.max(Number(P.reviewed[key])||0,Number(time)||0)}

const learningMembers=new Map();for(const c of D.cards){const k=learnKey(c.id);if(!learningMembers.has(k))learningMembers.set(k,[]);learningMembers.get(k).push(c.id)}
function members(id){return learningMembers.get(learnKey(id))||[]}
function pStatus(id){const ids=[learnKey(id),...members(id)];return ids.some(x=>S.known.has(x))?'mastered':ids.some(x=>P.again.has(x))?'review':'unseen'}
function pStar(id){return [learnKey(id),...members(id)].some(x=>S.stars.has(x))}
// Expand shared states for legacy reader, retain IDs that are no longer in this version.
for(const c of D.cards){if(pStatus(c.id)==='mastered')S.known.add(c.id);if(pStar(c.id))S.stars.add(c.id)}
let PS=null,pAnswer=true,pMasterTab='opening',pFocus='all';
function pMark(id,status){for(const x of [...members(id),learnKey(id)]){S.known.delete(x);P.again.delete(x)}if(status==='mastered')for(const x of [...members(id),learnKey(id)])S.known.add(x);if(status==='review')P.again.add(learnKey(id));P.reviewed[learnKey(id)]=Date.now();save()}
function save(){try{let latest={};try{const v=JSON.parse(localStorage.getItem(PK)||'{}');if(v&&typeof v==='object'&&!Array.isArray(v))latest=v}catch(e){}if(!storageHealthy){toast('原进度格式异常，已保留备份；本次修改暂不覆盖原记录');return}const portable={...P,again:[...P.again]};localStorage.setItem(PK,JSON.stringify({...saved,...latest,known:[...S.known],stars:[...S.stars],font:S.font,focus:S.focus,readMode:S.readMode,portable}));}catch(e){toast('浏览器未允许保存；本次仍可正常背诵')}progress()}
function pCards(ex=P.exam,section=null){const seen=new Set();return D.cards.filter(c=>{if(c.mergedInto||D.readingAliases?.[c.id]||!c.examTags.includes(ex)||(section!==null&&(ex==='sh'?!c.sh27Sections?.includes(Number(section)):c.portableSections[ex]!==Number(section))))return false;const k=learnKey(c.id);if(seen.has(k))return false;seen.add(k);return true})}
function pCounts(ex){const a=pCards(ex);return {total:a.length,mastered:a.filter(c=>pStatus(c.id)==='mastered').length,review:a.filter(c=>pStatus(c.id)==='review').length,unseen:a.filter(c=>pStatus(c.id)==='unseen').length}}
function progress(){if(typeof P==='undefined')return;const n=pCounts(P.exam);$('progressText').textContent=(P.exam==='cdb'?'国开 ':'上海 ')+n.mastered+' / '+n.total;$('progressBar').style.width=(n.total?n.mastered/n.total*100:0)+'%'}
function pButton(label,action,value='',extra=''){return `<button data-paction="${action}" data-pvalue="${esc(value)}" ${extra}>${label}</button>`}
function pSwitch(){return `<div class="p-switch" aria-label="切换考试">${['cdb','sh'].map(ex=>pButton(ex==='cdb'?'国开行':'上海选调','exam',ex,`aria-pressed="${P.exam===ex}"`)).join('')}</div>`}
function nav(){navLegacy();const old=$('nav').innerHTML;$('nav').innerHTML=pButton('首页 · 打开就背','home')+pButton('国开行备考','exam','cdb')+pButton('上海选调备考','exam','sh')+pButton('继续上次背诵','resume')+pButton('今日待背','today')+pButton('我的重点','focus')+pButton('全库搜索','search')+`<details class="p-oldnav" ${!pIsView()?'open':''}><summary>全文阅读与原有工具</summary>${old}</details>`;progress()}
function pIsView(){return ['home','portable-exam','portable-card','portable-search','portable-focus','sh27-mocks','sh-city-topics'].includes(S.view)}
function pShow(view){S.view=view;$('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'auto'})}
function pHome(){return `<section class="p-home"><h1>打开就背</h1><div class="p-entries">${pButton('<b>国开行备考</b><span>行史 · 时政 · 专业 · 主观题</span>','exam','cdb')}${pButton('<b>上海选调备考</b><span>八个申论热点 · 市情时政 · 行测</span>','exam','sh')}</div><div class="p-shortcuts">${pButton('继续上次背诵','resume','',P.last?'':'disabled')}${pButton('今日待背 · '+(P.exam==='cdb'?'国开行':'上海'),'today')}${pButton('我的重点','focus')}${pButton('随机背10条','random')}${pButton('全库搜索','search')}</div>${P.last?`<p class="p-muted">上次：${esc(cardMap.get(canonicalCardId(P.last.currentId))?.title||'已保存的位置')}</p>`:''}<details class="p-extra"><summary>全文阅读与工具</summary><div class="p-links"><button data-nav="H">行史与市情全文</button><button data-nav="W">国开行申论全文</button><button data-nav="S">上海申论全文</button><button data-nav="calc">金融计算器</button><button data-nav="newsfull">时政文档全文</button><button data-nav="library">资料目录</button><button data-course="H" data-domain="邮储银行">邮储银行</button><button data-course="H" data-domain="农业银行">农业银行</button></div></details></section>`}
function pExam20261028(){const ex=P.exam,n=pCounts(ex);return `${pSwitch()}<h1>${ex==='cdb'?'国开行备考':'上海选调备考'}</h1><p class="p-muted">未背 ${n.unseen} · 需再背 ${n.review} · 已掌握 ${n.mastered} / ${n.total}</p><div class="p-actions">${pButton('立刻开始背诵','start')}${pButton('继续本场上次','resumeExam')}${pButton('今日待背','today')}</div><div class="p-chapters">${D.portable.tracks[ex].map((t,i)=>{const cs=pCards(ex,i);return `<section><div>${pButton(`<b>${i+1}. ${esc(t)}</b><span>${cs.length}条</span>`,'section',i)}</div>${ex==='sh'&&i===4?`<div class="p-topic-list">${D.portable.topics.map((t,j)=>pButton(t,'topic',j)).join('')}</div>`:''}${ex==='sh'&&i===6?`<div class="p-topic-list">${pButton('科学推理 · 独立专项','subcat','C')}${pButton('资料分析 · 常用公式','subcat','DA')}${pButton('数量关系','subcat','M')}${pButton('言语理解','subcat','V')}${pButton('判断推理','subcat','J')}</div>`:''}<details><summary>选知识点</summary>${pList(cs)}</details></section>`}).join('')}${ex==='cdb'?`<section>${pButton(D.portable.auxiliary,'section',6)}<details><summary>选英语、EPI与常识知识点</summary>${pList(pCards(ex,6))}</details></section>`:''}</div>${ex==='sh'?`<details class="p-extra"><summary>上海近期重点时政 · 时间顺序</summary>${pList(['SHP03','SHP04','SHP05'].map(id=>cardMap.get(id)))}</details>`:''}<details class="p-extra"><summary>${ex==='sh'?'十大申论主题 · 选主题再背':'金融计算 · 公式与例题速达'}</summary>${ex==='sh'?D.portable.topics.map((t,i)=>pButton(t,'topic',i)).join(''):pList(pCards(ex,4).filter(c=>/年金|NPV|收益率|P\/|市盈率|六个系数/i.test(c.title)))}</details>`}
function pList(cs){return `<div class="p-list">${cs.map(c=>pButton(`<span>${esc(c.title)}</span><small>${{unseen:'未背',review:'需再背',mastered:'已掌握'}[pStatus(c.id)]}${pStar(c.id)?' · ★':''}</small>`,'open',c.id)).join('')||'<p>这里暂时没有知识点。</p>'}</div>`}
function pStart(ids,title,exam=P.exam){const seen=new Set();ids=canonicalIds(ids).filter(id=>{const c=cardMap.get(id),k=learnKey(id);if(!c||seen.has(k))return false;seen.add(k);return true});PS={exam,title,ids,index:0,currentId:ids[0]||'',onlyUnknown:!!P.onlyUnknown};pAnswer=true;pMasterTab='opening';pShow('portable-card')}
function pPool(){return PS?PS.ids.filter(id=>!PS.onlyUnknown||pStatus(id)!=='mastered'):[]}
function pRemember(){if(!PS)return;P.exam=PS.exam;P.last=JSON.parse(JSON.stringify(PS));P.byExam[PS.exam]=P.last;save()}
function pResume(examOnly=false){const s=examOnly?P.byExam[P.exam]:P.last;if(!s){pStart(pCards().map(c=>c.id),'本场全部');return}PS=JSON.parse(JSON.stringify(s));PS.ids=canonicalIds(PS.ids);PS.currentId=canonicalCardId(PS.currentId);if(!PS.ids.includes(PS.currentId))PS.currentId=PS.ids[0]||'';PS.index=Math.max(0,PS.ids.indexOf(PS.currentId));P.exam=PS.exam;pAnswer=true;pMasterTab='opening';pShow('portable-card')}
function pMove(delta){const ids=pPool();if(!ids.length)return;let ix=ids.indexOf(PS.currentId);if(ix<0)ix=Math.min(PS.index,ids.length-1);else ix=(ix+delta+ids.length)%ids.length;PS.index=ix;PS.currentId=ids[ix];pAnswer=true;pMasterTab='opening';pShow('portable-card')}
function pShuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function pDate(){const t=new Date();return [t.getFullYear(),t.getMonth()+1,t.getDate()].join('-')}
function pToday(){const k=pDate()+'/'+P.exam;if(!P.daily[k])P.daily[k]=pCards().filter(c=>pStatus(c.id)!=='mastered').sort((a,b)=>(pStatus(a.id)==='review'?0:1)-(pStatus(b.id)==='review'?0:1)).slice(0,20).map(c=>c.id);pStart(P.daily[k].filter(id=>pStatus(id)!=='mastered'),'今日待背 · 最多20条');save()}
function pLines(a,tag='p'){return (Array.isArray(a)?a:[a]).filter(Boolean).map(x=>`<${tag}>${esc(typeof x==='string'?x:JSON.stringify(x))}</${tag}>`).join('')}
function pMaster(m){const tabs=[['opening','开头'],['axes','分论点'],['body0','主体一'],['body1','主体二'],['body2','主体三'],['ending','结尾'],['cases','词与案例']];let content=pMasterTab==='axes'?`<ol>${pLines(m.axes,'li')}</ol>`:pMasterTab==='cases'?`<p>${m.words.map(esc).join(' · ')}</p>${m.cases.map(x=>`<h3>${esc(x.title)}</h3><p>${esc(x.text)}</p>`).join('')}`:pLines(pMasterTab.startsWith('body')?m.bodies[Number(pMasterTab.slice(-1))]:m[pMasterTab]);return `<p class="p-claim">${esc(m.claim)}</p><nav class="p-tabs" aria-label="母版快速定位">${tabs.map(([key,label])=>pButton(label,'mastertab',key,`aria-pressed="${pMasterTab===key}"`)).join('')}</nav><section class="p-master-part"><h3>${tabs.find(x=>x[0]===pMasterTab)?.[1]||'开头'}</h3>${content}</section><details class="p-extra"><summary>完整母版 · 开头、主体、结尾</summary><h3>开头</h3>${pLines(m.opening)}<h3>三个分论点</h3><ol>${pLines(m.axes,'li')}</ol>${m.bodies.map((p,i)=>`<h3>${esc(m.axes[i])}</h3>${pLines(p)}`).join('')}<h3>结尾</h3>${pLines(m.ending)}</details><p class="p-muted">整理表达。根据材料替换对象、关键词与案例。</p>`}
function pEssay(c){const e=c.essay||{},t=e.teaching||{},m=cardMap.get(c.masterRefs?.[0]||'MB02')?.master;let axes=t.axes||e.relationshipLogic?.axes||e.modelLogic||[];if(typeof axes==='string')axes=axes.split(/[；→]/);if(!Array.isArray(axes))axes=[];axes=axes.filter(x=>typeof x==='string');if(axes.length<3&&e.paragraphs)axes=e.paragraphs.filter(x=>/主体|分论|论证/.test(x.role)).slice(0,3).map(x=>x.text.split(/[。；]/)[0]);if(axes.length<3)axes=m.axes;
 if(e.type==='bank'&&!e.sections?.some(x=>/三个分论点/.test(x[0])))return `<p class="p-label">直接背诵 · 结构与表达</p><p class="p-claim">${esc(e.core||c.title)}</p>${(e.sections||[]).slice(0,2).map(([title,items])=>`<h3>${esc(title)}</h3>${pLines(items)}`).join('')}<details class="p-extra"><summary>完整框架与用法</summary>${essayBody(c)}</details>`;
 if(e.sections?.some(x=>/三个分论点/.test(x[0])))axes=e.sections.find(x=>/三个分论点/.test(x[0]))[1];
 let paragraph=e.paragraph;if(!paragraph&&e.paragraphs)paragraph=(e.paragraphs.find(x=>/主体|论证/.test(x.role))||e.paragraphs[1]||e.paragraphs[0])?.text;if(!paragraph&&e.sections){const a=e.sections.find(x=>/背诵|直接背|段落/.test(x[0]));paragraph=a?.[1]?.join('')}paragraph=paragraph||m.bodies[0];let core=e.core||c.memory?.points?.[0]||m.claim;
 return `<p class="p-label">中心论点</p><p class="p-claim">${esc(core)}</p><h3>三个分论点</h3><ol>${pLines(axes.slice(0,3),'li')}</ol><h3>直接背这一段</h3>${pLines(paragraph)}<h3>${P.exam==='sh'?'上海素材':'可背案例与应用素材'}</h3>${e.case?pLines(String(e.case).replace(/^(?:津仕|中公|jinshi)[^：:]*[：:]/i,'').replace('背例不背数字：','')):m.cases.slice(0,1).map(x=>`<p><b>${esc(x.title)}</b>：${esc(x.text)}</p>`).join('')}<div class="p-links">${(c.masterRefs||[m.id]).map(id=>pButton('复用母版：'+esc(cardMap.get(id).title),'open',id)).join('')}</div>${e.relationshipLogic?`<details class="p-extra"><summary>关系与逻辑边界</summary>${pLines([e.relationshipLogic.judgment,e.relationshipLogic.chain,e.relationshipLogic.boundary])}</details>`:''}<details class="p-extra"><summary>好句、完整范文与教学讲解</summary>${essayBody(c)}</details>`}
function pUnfold(html){return (html||'').replace(/<details\b[^>]*>/g,'<section class="p-solution">').replace(/<\/details>/g,'</section>').replace(/<summary[^>]*>/g,'<h4>').replace(/<\/summary>/g,'</h4>')}
function pKnowledge20261028(c){if(c.normative)return normativeBody(c);if(c.master)return pMaster(c.master);if(c.essay)return pEssay(c);if(c.recitation){const r=c.recitation;return `${(r.quotes||[]).map(q=>`<blockquote><p>${esc(q.text)}</p><small>${esc(q.label)}</small></blockquote>`).join('')}${pLines(r.core)}<details class="p-extra"><summary>背景、记忆表述与易混点</summary>${pLines([r.background,r.recite,...(r.exam||[])])}</details>`}
 const l=c.lesson,m=c.memory||{};if(l)return `<h3>核心知识与公式</h3>${pLines([l.knowledge,l.formula])}<h3>方法与条件</h3>${pLines(l.method)}<h3>典型例题</h3>${pLines(l.problem)}<h3>答案与步骤</h3>${pLines([l.answer,l.steps])}${l.pitfalls?`<details class="p-extra"><summary>易错点</summary>${pLines(l.pitfalls)}</details>`:''}`;
 let h=pLines(m.points||[]);if(m.boundary)h+=`<p class="p-condition">${esc(m.boundary)}</p>`;
 const professional=['A','E','F','G','K','M','C'].includes(c.cat);if(professional){if((c.html||'').length<6500)h+=`<div class="p-example">${pUnfold(c.html)}</div>`;else{const examples=(c.html||'').match(/<div class="practice-stem">[\s\S]*?<\/div>\s*<details[\s\S]*?<\/details>/g)||[];h+=examples.map(pUnfold).join('');}}
 if(c.enrichment&&typeof c.enrichment==='object'){const e=c.enrichment;h+=`<h3>条件与公式</h3>${pLines([e.focus,e.formula])}<h3>典型例题</h3>${pLines(e.question)}<h3>答案与关键步骤</h3>${pLines([e.answer,e.trap])}`}
 if(!h.trim())h=pUnfold(c.html);return h+`<details class="p-extra"><summary>完整讲解、推导与原有例题</summary>${c.foundationHtml||''}${c.html||''}${typeof c.enrichment==='string'?c.enrichment:''}</details>`}
function pCard(){if(!PS)return pHome();const ids=pPool();let c;if(!ids.length)return `${pSwitch()}<h1>这一组已完成</h1><p>${PS.ids.length?'当前筛选中没有未掌握内容。':'当前没有待背知识点。'}</p>${pButton('返回本场目录','exam',P.exam)}${pButton('查看本组全部','showall')}`;if(!ids.includes(PS.currentId))PS.currentId=ids[Math.min(PS.index,ids.length-1)];PS.index=ids.indexOf(PS.currentId);c=cardMap.get(PS.currentId);pRemember();
 return `${pSwitch()}<div class="p-session"><span>${esc(PS.title)} · ${PS.index+1} / ${ids.length}</span>${pButton('章节目录','exam',P.exam)}</div><label class="p-filter"><input type="checkbox" id="pOnlyUnknown" ${PS.onlyUnknown?'checked':''}> 只背未掌握（未背＋需再背）</label><article class="p-single" id="pCurrent"><p class="p-label">${esc(c.id)} · ${{unseen:'未背',review:'需再背',mastered:'已掌握'}[pStatus(c.id)]}</p><h1>${esc(c.title)}</h1><div class="p-card-tools">${pButton(pAnswer?'隐藏答案':'显示答案','answer')}${pButton(pStar(c.id)?'★ 我的重点':'☆ 加入重点','star',c.id)}${pButton('全文与例题','full',c.id)}</div>${pAnswer?`<div class="p-answer">${pKnowledge(c)}</div><details class="p-extra p-metadata"><summary>来源与核验信息</summary>${sourceFold(c)}<p>原分类：${esc(c.cat)} · ${esc(c.group||'')}</p></details>`:'<p class="p-hidden-answer">先回忆，再点击“显示答案”核对。</p>'}<div class="p-status" aria-label="背诵状态">${[['unseen','未背'],['review','需再背'],['mastered','已掌握']].map(([k,t])=>pButton(t,'status',k,`aria-pressed="${pStatus(c.id)===k}"`)).join('')}</div></article><nav class="p-turn" aria-label="背诵翻页">${pButton('上一条','prev')}${pButton('随机','shuffle')}${pButton('下一条','next')}</nav>`}
function pSearchResults(){const q=S.q.trim().toLowerCase();return q?D.cards.filter(c=>!c.mergedInto&&!D.readingAliases?.[c.id]&&[c.id,c.title,c.group,c.domain,c.html,JSON.stringify(c.memory),JSON.stringify(c.essay),JSON.stringify(c.recitation),JSON.stringify(c.searchAliases),JSON.stringify(c.mock),JSON.stringify(c.shMethod),JSON.stringify(c.shEssay),JSON.stringify(c.shQuote)].join(' ').toLowerCase().includes(q)):[]}
function pSearch(){const q=S.q.trim().toLowerCase(),cs=pSearchResults();return `<h1>全库搜索</h1><p class="p-muted">在上方输入主题、公式、原话或编号。</p>${q?`<p>${cs.length}条结果</p>${pList(cs)}`:''}`}
function pFocusView(){const cs=pCards().filter(c=>(pFocus==='star'?pStar(c.id):pFocus==='review'?pStatus(c.id)==='review':pStar(c.id)||pStatus(c.id)==='review'));return `${pSwitch()}<h1>我的重点</h1><div class="p-tabs">${[['all','全部重点'],['star','我的收藏'],['review','需再背']].map(([k,t])=>pButton(t,'focusfilter',k,`aria-pressed="${pFocus===k}"`)).join('')}</div>${pButton('连续背这些重点','focusstart')}<p class="p-muted">${cs.length}条</p>${pList(cs)}`}
function render(){document.documentElement.classList.toggle('focus-reader',pIsView()?false:S.focus);if(!pIsView()){document.documentElement.classList.toggle('portable-ui',false);renderLegacy();return}document.documentElement.classList.toggle('portable-ui',true);document.documentElement.style.setProperty('--portable-font',Math.max(18,S.font)+'px');nav();$('crumbText').textContent=S.view==='home'?'随身背诵':P.exam==='cdb'?'国开行':'上海选调';$('printBtn').textContent='打印当前内容';$('main').innerHTML=S.view==='home'?pHome():S.view==='portable-exam'?pExam():S.view==='portable-card'?pCard():S.view==='portable-search'?pSearch():S.view==='sh27-mocks'?shMockIndex():S.view==='sh-city-topics'?cityTopicIndex():pFocusView()}
function portableClick(e){const b=e.target.closest('button');if(!b)return false;const a=b.dataset.paction,v=a==='open'||a==='full'?canonicalCardId(b.dataset.pvalue):b.dataset.pvalue;if(!a){if(b.dataset.known){const id=b.dataset.known;pMark(id,pStatus(id)==='mastered'?'unseen':'mastered');render();return true}if(b.dataset.star){pToggleStar(b.dataset.star);render();return true}if(b.id==='larger'||b.id==='smaller'){S.font=Math.max(18,Math.min(30,S.font+(b.id==='larger'?1:-1)));document.documentElement.style.setProperty('--text',S.font+'px');save();render();return true}if(b.id==='printBtn'&&pIsView()){const c=S.view==='portable-card'?cardMap.get(PS?.currentId):null;$('printArea').innerHTML=c?`<h1>${esc(c.title)}</h1>${pKnowledge(c)}`:$('main').innerHTML;window.print();return true}return false}
 if(a==='home')pShow('home');if(a==='exam'){P.exam=v;save();pShow('portable-exam')}if(a==='start')pStart(pCards().map(c=>c.id),'本场全部');if(a==='section')pStart(pCards(P.exam,Number(v)).map(c=>c.id),D.portable.tracks[P.exam][Number(v)]||D.portable.auxiliary);if(a==='topic')pStart(pCards('sh').filter(c=>c.cat==='S'&&c.portableTopic===Number(v)).map(c=>c.id),D.portable.topics[Number(v)],'sh');
 if(a==='open'){const c=cardMap.get(v);if(!c)return true;const view=S.view;const ex=c.examTags.includes(P.exam)?P.exam:c.examTags[0]||P.exam;let list=view==='portable-search'?pSearchResults():c.master?D.portable.masters.map(id=>cardMap.get(id)).filter(c=>c.examTags.includes(ex)):pCards(ex,ex==='sh'?(c.sh27Sections?.[0]??null):c.portableSections[ex]??null);if(!list.some(x=>x.id===v))list=[c,...list];pStart(list.map(x=>x.id),view==='portable-search'?'搜索结果':c.master?'申论母版库':D.portable.tracks[ex][ex==='sh'?(c.sh27Sections?.[0]??null):c.portableSections[ex]]||'选定知识点',ex);PS.onlyUnknown=false;PS.currentId=v;PS.index=PS.ids.indexOf(v);pRemember();render()}
 if(a==='subcat'){const cs=pCards().filter(c=>v==='DA'?c.id.startsWith('DA')||c.cat==='M'&&/资料分析/.test(c.group):c.cat===v&&(v!=='M'||!c.id.startsWith('DA')));pStart(cs.map(c=>c.id),v==='DA'?'资料分析 · 常用公式':META[v].name)}if(a==='resume')pResume();if(a==='resumeExam')pResume(true);if(a==='today')pToday();if(a==='random')pStart(pShuffle(pCards().filter(c=>!P.onlyUnknown||pStatus(c.id)!=='mastered').map(c=>c.id)).slice(0,10),'随机背10条');if(a==='focus')pShow('portable-focus');if(a==='focusfilter'){pFocus=v;render()}if(a==='focusstart')pStart(pCards().filter(c=>(pFocus==='star'?pStar(c.id):pFocus==='review'?pStatus(c.id)==='review':pStar(c.id)||pStatus(c.id)==='review')).map(c=>c.id),'我的重点');if(a==='search'){S.q='';$('search').value='';pShow('portable-search');$('search').focus()}if(a==='prev')pMove(-1);if(a==='next')pMove(1);if(a==='shuffle'){const ids=pPool().filter(id=>id!==PS.currentId);if(ids.length){PS.currentId=ids[Math.floor(Math.random()*ids.length)];pAnswer=true;pMasterTab='opening';render();window.scrollTo({top:0,behavior:'auto'})}}if(a==='answer'){pAnswer=!pAnswer;render()}if(a==='mastertab'){pMasterTab=v;render()}if(a==='star'){pToggleStar(v);render()}if(a==='status'){const ix=PS.index;pMark(PS.currentId,v);if(PS.onlyUnknown&&v==='mastered'){const ids=pPool();PS.currentId=ids[Math.min(ix,ids.length-1)]||'';pAnswer=true}render()}if(a==='showall'){PS.onlyUnknown=false;P.onlyUnknown=false;render()}if(a==='full'){const c=cardMap.get(v);go(c.cat,c.id)}return true}
function pToggleStar(id){const active=pStar(id);for(const x of [...members(id),learnKey(id)])S.stars.delete(x);if(!active)for(const x of [...members(id),learnKey(id)])S.stars.add(x);save()}
document.addEventListener('change',e=>{if(e.target.id==='pOnlyUnknown'&&PS){PS.onlyUnknown=e.target.checked;P.onlyUnknown=PS.onlyUnknown;render();pRemember()}});
document.addEventListener('keydown',e=>{if(S.view!=='portable-card'||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target?.tagName||''))return;if(e.key==='ArrowRight'){e.preventDefault();pMove(1)}if(e.key==='ArrowLeft'){e.preventDefault();pMove(-1)}if(e.key===' '){e.preventDefault();pAnswer=!pAnswer;render()}});

