let shDocState=null;
function shNormal(cs){return cs.filter(c=>!c.mock)}
function pExamBeforeCity(){if(P.exam!=='sh')return pExam20261028();const n=pCounts('sh');return `${pSwitch()}<h1>上海选调备考</h1><div class="p-actions">${pButton('继续上次背诵','resumeExam')}${pButton('只背未掌握','sh-quick','unknown')}${pButton('今日待背','today')}</div><div class="p-tabs" aria-label="上海快速背诵">${pButton('时政一起背','sh-quick','current')}${pButton('上海专项','sh-quick','local')}${pButton('重要论述','section','4')}${pButton('申论母版','section','9')}${pButton('模拟卷考题','sh-mocks')}</div><p class="p-muted">未背 ${n.unseen} · 需再背 ${n.review} · 已掌握 ${n.mastered} / ${n.total}（含模拟考题）</p><div class="p-chapters">${D.sh27.moduleNames.map((name,i)=>{const all=pCards('sh',i),cs=shNormal(all);return `<section><div>${pButton(`<b>${String.fromCharCode(65+i)}. ${esc(name)}</b><span>${cs.length}条</span>`,'section',i)}</div>${i===6?`<div class="p-topic-list">${pButton('科学推理 · 单独背','subcat','C')}${pButton('资料分析公式','subcat','DA')}${pButton('判断推理','subcat','J')}${pButton('言语理解','subcat','V')}${pButton('数量关系','subcat','M')}${pButton('6套行测 · 720题','sh-mocks')}</div>`:''}${i===8?`<details><summary>按12个主题背</summary><div class="p-topic-list">${D.sh27.themeIDs.map(id=>pButton(esc(cardMap.get(id).title),'open',id)).join('')}</div></details>`:''}${i===9?`<div class="p-topic-list">${D.portable.masters.filter(id=>cardMap.get(id).examTags.includes('sh')).map(id=>pButton(esc(cardMap.get(id).title),'open',id)).join('')}</div>`:''}<details><summary>选知识点</summary>${pList(cs)}</details></section>`}).join('')}</div><details class="p-extra"><summary>上海近期重点 · 原专题保留</summary>${pList(D.sh27.protected.map(id=>cardMap.get(id)))}</details><details class="p-extra"><summary>官方考试依据与教学分类</summary><p>${esc(D.sh27.officialBasis.act.join('、'))}为2027政策问答列出的行测部分；行测120分钟、申论150分钟。</p><p>${esc(D.sh27.officialBasis.note)}</p><button data-source="${D.sh27.officialBasis.ref}">核对政策问答</button></details>`}
function shMockIndex(){const papers=Object.keys(D.sh27.papers);return `${pSwitch()}<h1>模拟卷考题</h1><p class="p-muted">六套行测720题，按卷与专项连续复习。题目、参考解析及原页均已内嵌。</p><div class="p-tabs">${pButton('只背未掌握题','sh-mock-unseen')}${pButton('科学推理题','sh-mock-topic','science')}${pButton('政治、时政与常识题','sh-mock-topic','current')}</div><div class="p-chapters">${papers.map(code=>{const cs=D.cards.filter(c=>c.mock?.paper===code),n=cs.filter(c=>pStatus(c.id)==='mastered').length;return `<section>${pButton((code.startsWith('ZG')?'中公':'津仕')+'第'+code.slice(-1)+'套 · '+n+' / '+cs.length+' 已掌握','sh-paper',code)}<details><summary>选题</summary>${pList(cs)}</details></section>`}).join('')}</div><h2>六套申论 · 原题与参考答案</h2>${pList(D.cards.filter(c=>c.shMockEssay))}`}
function shPageFrame(paper,kind,index){const doc=D.sh27.papers[paper]?.[kind];if(!doc)return '';index=Math.min(Math.max(index,0),doc.pages.length-1);shDocState={paper,kind,index};const pg=doc.pages[index];return `<div class="p-doc-toolbar">${pButton('前页','sh-docpage',`${paper}:${kind}:${index-1}`)}<span>${kind==='q'?'题本':'解析'} ${index+1} / ${doc.pages.length}</span>${pButton('后页','sh-docpage',`${paper}:${kind}:${index+1}`)}</div><img class="p-source-page" loading="lazy" src="${D.sh27.images[pg.image]}" alt="${esc(doc.name)} 第${index+1}页"><details><summary>本页可搜索文字</summary><p class="p-original-text">${esc(pg.text)}</p></details>`}
function shRelated(c){return canonicalIds(c.relatedKnowledge||[]).map(id=>cardMap.get(id)).filter(Boolean)}
function shQuestion(c){const q=c.mock;const links=shRelated(c);const figure=/如图|下图|图形|图中|下列.*图|示意图|立体|平面图/.test(q.question)||q.question.length<80;let h=`<p class="p-label">${q.paper.startsWith('ZG')?'中公':'津仕'}第${q.paper.slice(-1)}套 · 第${q.no}题</p>`;
 if(links.length){const k=links[0];h+=`<h3>先背相关知识</h3>${pLines((k.memory?.points||[]).slice(0,2))}<div class="p-links">${links.map(k=>pButton(esc(k.title),'open',k.id)).join('')}</div>`}
 h+=`<h3>原题</h3><p class="p-original-text">${esc(q.question)}</p>${figure?`<details open class="p-extra"><summary>图形、选项与原页</summary><img loading="lazy" class="p-source-page" src="${D.sh27.images[D.sh27.papers[q.paper].q.pages[q.page-1].image]}" alt="本题所在题本第${q.page}页"></details>`:''}<h3>参考答案</h3><p class="p-reference-answer">${esc(q.answer)}</p><details class="p-extra"><summary>展开原卷解析与计算步骤</summary><p class="p-original-text">${esc(q.analysis||'原卷本题仅提供答案字母，未附文字解析；可查看关联知识和原始题页。')}</p>${q.numberingNote?`<p class="p-muted">${esc(q.numberingNote)}</p>`:''}${q.paper==='JS3'?'<p class="p-muted">扫描版文字已识别，公式和图示以旁边原页为准。</p>':''}</details><details class="p-extra"><summary>材料、表格与原始解析 · 离线翻页</summary><div class="p-links">${pButton('看题本与材料','sh-docpage',`${q.paper}:q:${q.page-1}`)}${pButton('看解析原页','sh-docpage',`${q.paper}:a:${Math.max(0,(q.answerPage||1)-1)}`)}</div><div id="shDocFrame">${shPageFrame(q.paper,'q',q.page-1)}</div></details>`;return h}
function shEssay(c){const e=c.shEssay,m=cardMap.get(e.master)?.master,k=cardMap.get(e.caseId);let text=k?.recitation?.recite||k?.essay?.paragraph||k?.memory?.points?.slice(0,2).join('；')||'';return `<p class="p-label">中心论点</p><p class="p-claim">${esc(e.core)}</p><h3>三个分论点</h3><ol>${pLines(e.axes,'li')}</ol><h3>直接背论证段</h3>${pLines(e.paragraph)}<h3>上海素材</h3>${pLines(text)}<div class="p-links">${pButton('背案例完整内容','open',e.caseId)}${pButton('复用母版：'+esc(m.title),'open',e.master)}</div><details class="p-extra"><summary>可用开头</summary>${pLines(e.opening)}</details><details class="p-extra"><summary>可用结尾</summary>${pLines(e.ending)}</details>`}
function shMethod(c){const m=c.shMethod;return `<p class="p-label">题型识别</p>${pLines(m.identify)}<h3>考场直接用的结构</h3><ol>${pLines(m.structure,'li')}</ol><h3>规范表达</h3>${pLines(m.phrases)}<h3>短示范 · 教学整理</h3>${pLines(m.example)}<details class="p-extra"><summary>材料落点与结构边界</summary>${pLines(m.logic)}</details>`}
function shEssayPaper(c){const q=c.shMockEssay,p=D.sh27.essayPapers[q.paper],m=c.shModelExtract;return `${m?`<p class="p-label">范文逻辑提炼 · 整理表达</p><p class="p-claim">${esc(m.core)}</p><h3>三个分论点</h3><ol>${pLines(m.axes,'li')}</ol><h3>直接背这一段</h3>${pLines(m.paragraph)}<div class="p-links">${pButton('对应上海主题素材','open',m.caseId)}${pButton('复用母版','open',m.master)}</div>`:`<h3>参考作答</h3><p class="p-original-text">${esc(q.answerOnly||q.block)}</p>`}<details class="p-extra"><summary>原题、要求与参考范文原文</summary><p class="p-original-text">${esc(q.block)}</p></details><details class="p-extra"><summary>完整给定材料</summary><p class="p-original-text">${esc(p.materials)}</p></details><details class="p-extra"><summary>全卷参考答案与完整范文</summary><p class="p-original-text">${esc(p.reference)}</p></details><div class="p-links">${pButton('六类题型方法','section','7')}${pButton('申论母版库','section','9')}</div>`}
function pKnowledgeBeforeCity(c){if(c.normative)return normativeBody(c);if(c.mock)return shQuestion(c);if(c.shMethod)return shMethod(c);if(c.shEssay)return shEssay(c);if(c.shMockEssay)return shEssayPaper(c);if(c.shQuote){const q=c.shQuote;return `<blockquote>${pLines(q.text)}</blockquote><p class="p-muted">${esc(q.occasion)}</p><h3>申论转用 · 整理表达</h3>${pLines(q.use)}`}return pKnowledge20261028(c)}
function shAction(e){const b=e.target.closest('button');if(!b)return false;const a=b.dataset.paction,v=a==='open'||a==='full'?canonicalCardId(b.dataset.pvalue):b.dataset.pvalue;if(a==='city-topics'){P.exam='sh';pShow('sh-city-topics');return true}if(a==='city-topic'){cityTopicID=v;pShow('sh-city-topics');return true}if(a==='city-topic-knowledge'){const t=D.shCityTopics.find(x=>x.id===v);pStart(t.knowledge,t.title,'sh');return true}if(a==='city-topic-master'){const [id,part]=v.split(':');const t=D.shCityTopics.find(x=>x.id===id);pStart([t.master,...(t.extraMasters||[])],t.title+' · 母版','sh');pMasterTab=part||'opening';render();return true}if(a==='city-basics'){pStart(['SX11','SHC10','SHC11','SHN109','SHN111','SHN112','SHN125','SHC08','SHN108','SHN118','SHC01','SHC02'],'上海基础概念','sh');return true}if(a==='city-news'){pStart(['SHC04','SHC05','SHC07','SHC09','SHP03','SHP04','SHP05','T08','SHP02','SHN122','SHN126'],'上海热点与重要部署','sh');return true}if(a==='open'&&cardMap.get(v)?.mock){const c=cardMap.get(v);pStart(D.cards.filter(x=>x.mock?.paper===c.mock.paper).map(x=>x.id),'本卷连续背题','sh');PS.onlyUnknown=false;PS.currentId=v;render();return true}if(a==='section'&&P.exam==='sh'){pStart(shNormal(pCards('sh',Number(v))).map(c=>c.id),D.sh27.moduleNames[Number(v)],'sh');return true}if(a==='sh-mocks'){P.exam='sh';S.view='sh27-mocks';render();window.scrollTo({top:0});return true}if(a==='sh-paper'){pStart(D.cards.filter(c=>c.mock?.paper===v).map(c=>c.id),(v.startsWith('ZG')?'中公':'津仕')+'第'+v.slice(-1)+'套','sh');return true}if(a==='sh-mock-unseen'){pStart(D.cards.filter(c=>c.mock&&pStatus(c.id)!=='mastered').map(c=>c.id),'未掌握模拟题','sh');PS.onlyUnknown=true;render();return true}if(a==='sh-mock-topic'){const cs=D.cards.filter(c=>c.mock&&(v==='science'?/压强|浮力|电路|电功率|透镜|化学|生物|细胞|食物|生态系统|热量|光学|摩擦|杠杆|声音|机械|能量转化/.test(c.mock.question+c.mock.analysis):c.mock.no<=25));pStart(cs.map(c=>c.id),v==='science'?'科学推理模拟题':'政治时政与常识模拟题','sh');return true}if(a==='sh-docpage'){const [paper,kind,index]=v.split(':');$('shDocFrame').innerHTML=shPageFrame(paper,kind,Number(index));return true}if(a==='sh-quick'){let cs=shNormal(pCards('sh'));if(v==='current')cs=cs.filter(c=>c.sh27Sections.some(i=>[1,3].includes(i)));if(v==='local')cs=cs.filter(c=>c.sh27Sections.some(i=>[2,3,4,7,8,9].includes(i)));if(v==='unknown')cs=cs.filter(c=>pStatus(c.id)!=='mastered');pStart(cs.map(c=>c.id),v==='current'?'国家与上海时政':v==='local'?'上海专项':'未掌握知识','sh');if(v==='unknown'){PS.onlyUnknown=true;render()}return true}return false}


function canonicalCardId(id){const seen=new Set();while(D.readingAliases?.[id]&&!seen.has(id)){seen.add(id);id=D.readingAliases[id]}return id}
function canonicalIds(ids){return [...new Set((Array.isArray(ids)?ids:[]).map(canonicalCardId))].filter(id=>cardMap.has(id))}
function cityRelated(c){const ids=canonicalIds(c.relatedConcepts||[]).filter(id=>id!==c.id);return ids.length?`<div class="p-links">${ids.map(id=>pButton('相关概念：'+esc(cardMap.get(id).title),'open',id)).join('')}</div>`:''}
function cityMergedExamples(c){const ids=c.mergedExamples||[];return ids.length?`<details class="p-extra merged-examples"><summary>保留的原题、例题与解析 · ${ids.length}组</summary>${ids.map(id=>{const x=cardMap.get(id);return `<section><h3>${esc(x.title)}</h3>${bodyFor(x,true)}</section>`}).join('')}</details>`:''}
function pKnowledge(c){c=cardMap.get(canonicalCardId(c.id))||c;return pKnowledgeBeforeCity(c)+cityRelated(c)+cityMergedExamples(c)}
function memoryContent(c,print=false){c=cardMap.get(canonicalCardId(c.id))||c;return memoryContentBeforeCity(c,print)+cityRelated(c)+cityMergedExamples(c)}
function pExam(){const h=pExamBeforeCity();if(P.exam!=='sh')return h;return h.replace('</h1>','</h1><div class="p-actions">'+pButton('优先背：上海申论八个热点','city-topics')+'</div><div class="p-links">'+pButton('上海基础概念 · 从五个中心开始','city-basics')+pButton('上海热点与重要部署','city-news')+'</div>')}
let cityTopicID='Y3';
function cityTopicIndex(){const t=D.shCityTopics.find(x=>x.id===cityTopicID)||D.shCityTopics[0],m=cardMap.get(t.master).master;return `${pSwitch()}<h1>上海申论 · 八个热点优先背</h1><nav class="p-tabs city-topic-tabs" aria-label="八个申论热点">${D.shCityTopics.map(x=>pButton(x.shortTitle||x.title,'city-topic',x.id,`aria-pressed="${x.id===t.id}"`)).join('')}</nav><section class="p-answer"><h2>${esc(t.title)}</h2><div class="p-actions">${pButton('连续背本主题知识','city-topic-knowledge',t.id)}${pButton('直接背本主题母版','city-topic-master',t.id+':opening')}</div><h3>必背知识</h3>${t.cues.map(([id,indexes])=>{const c=cardMap.get(canonicalCardId(id)),ps=c.normative?.points||c.memory?.points||[];return `<section>${pLines(indexes.map(i=>ps[i]))}</section>`}).join('')}<h3>母版中心论点</h3><p class="p-claim">${esc(m.claim)}</p><h3>三个分论点</h3><ol>${pLines(m.axes,'li')}</ol><div class="p-tabs">${[['opening','开头'],['body0','主体一'],['body1','主体二'],['body2','主体三'],['ending','结尾'],['cases','素材与案例']].map(([key,label])=>pButton(label,'city-topic-master',t.id+':'+key)).join('')}</div><h3>直接背这一段</h3>${pLines(m.bodies[0])}<details class="p-extra"><summary>完整母版 · 开头、主体、结尾</summary><h3>开头</h3>${pLines(m.opening)}${m.axes.map((a,i)=>`<h3>${esc(a)}</h3>${pLines(m.bodies[i])}`).join('')}<h3>结尾</h3>${pLines(m.ending)}</details><details class="p-extra"><summary>本主题知识点目录</summary>${pList(canonicalIds(t.knowledge).map(id=>cardMap.get(id)))}</details><details class="p-extra"><summary>材料适用与组合</summary><p>${esc(t.prompt)}</p>${(t.extraMasters||[]).map(id=>pButton(cardMap.get(id).title,'open',id)).join('')}</details></section>`}

document.documentElement.classList.toggle('focus-reader',S.focus);$('focusBtn').textContent=S.focus?'退出专注':'专注阅读';
render();
